import type { Lang } from '@/lib/i18n/translations';
type LangMap = Record<Lang, string>;
const E: Omit<LangMap, 'en'> = { ms: '', tur: '', urd: '', ben: '', fas: '', zh: '', yue: '', ja: '', ru: '', es: '', ko: '', ta: '', si: '' };

export const MASJID_CONTENT = {
  hist_h: { en: `The First Masjids`, ms: `Masjid-Masjid Pertama`, tur: `İlk Mescitler`, urd: `پہلی مساجد`, ben: `প্রথম মসজিদসমূহ`, fas: `نخستین مسجدها`, zh: `最初的清真寺`, yue: `最初嘅清真寺`, ja: `最初のモスク`, ru: `Первые мечети`, es: `Las primeras mezquitas`, ko: `최초의 모스크`, ta: `முதல் மசூதிகள்`, si: `පළමු මස්ජිද` },
  hist_p1: { en: `The Prophet ﷺ built the Masjid of Quba just outside Madinah in Rabi al-Awwal of the first Hijri year, on his stopover during the Hijra. Allah describes it in the Qur'an as "a masjid founded on taqwa from the first day" (al-Tawba 9:108). The Prophet ﷺ said whoever purifies themselves at home, then goes to Quba and prays there, receives the reward of an 'umrah.`, ms: `Nabi ﷺ membina Masjid Quba di pinggir Madinah pada bulan Rabi' al-Awwal tahun pertama Hijrah, semasa persinggahan baginda dalam perjalanan Hijrah. Allah menyifatkannya dalam al-Qur'an sebagai "masjid yang didirikan atas dasar taqwa sejak hari pertama" (al-Tawbah 9:108). Nabi ﷺ bersabda sesiapa yang bersuci di rumah, kemudian pergi ke Quba dan solat di sana, akan memperoleh pahala seperti 'umrah.`, tur: `Peygamber ﷺ, hicretin ilk yılının Rebîülevvel ayında, hicret yolculuğundaki mola sırasında Medine'nin hemen dışında Kuba Mescidi'ni inşa etti. Allah onu Kur'an'da "ilk günden takva üzere kurulmuş bir mescit" olarak nitelendirir (et-Tevbe 9:108). Peygamber ﷺ, evinde temizlenip Kuba'ya gidip orada namaz kılan kimsenin bir umre sevabı alacağını buyurmuştur.`, urd: `نبی ﷺ نے ہجرت کے سفر کے دوران پہلے ہجری سال کے ربیع الاول میں مدینہ کے بالکل باہر مسجد قبا تعمیر کی۔ اللہ نے قرآن میں اسے "پہلے دن سے تقویٰ پر قائم مسجد" قرار دیا ہے (التوبہ ۹:۱۰۸)۔ نبی ﷺ نے فرمایا کہ جو شخص گھر پر پاکی حاصل کرے، پھر قبا جا کر وہاں نماز پڑھے، اسے عمرے کا ثواب ملتا ہے۔`, ben: `নবী ﷺ হিজরতের প্রথম বছরের রবিউল আউয়াল মাসে, হিজরত সফরের বিরতিতে মদিনার একদম বাইরে মসজিদে কুবা নির্মাণ করেন। আল্লাহ কুরআনে একে "প্রথম দিন থেকেই তাকওয়ার ভিত্তিতে প্রতিষ্ঠিত মসজিদ" বলে বর্ণনা করেছেন (আত-তাওবা ৯:১০৮)। নবী ﷺ বলেছেন, যে ব্যক্তি ঘরে পবিত্রতা অর্জন করে, তারপর কুবায় গিয়ে সেখানে নামাজ পড়ে, সে একটি উমরার সওয়াব পায়।`, fas: `پیامبر ﷺ در ربیع‌الاول سال نخست هجری، در توقفگاه خود در سفر هجرت، مسجد قبا را در بیرون مدینه بنا نهاد. خداوند در قرآن آن را «مسجدی که از روز نخست بر پایه تقوا بنا شده» توصیف می‌کند (التوبه ۹:۱۰۸). پیامبر ﷺ فرمود هر کس در خانه پاکیزه شود، سپس به قبا برود و در آنجا نماز گزارد، پاداش یک عمره دریافت می‌کند.`, zh: `先知 ﷺ 于希吉拉历元年赖比尔·敖外鲁月，在迁徙途中停留时，于麦地那城外建立了库巴清真寺。真主在《古兰经》中称其为「自首日起即建于敬畏之上的清真寺」（讨白9:108）。先知 ﷺ 说，凡在家中净身，然后前往库巴在那里礼拜者，获得一次副朝的回赐。`, yue: `先知 ﷺ 於希吉拉曆元年賴比爾・敖外魯月，喺遷徙途中停留時，喺麥地那城外建立咗庫巴清真寺。真主喺《古蘭經》中稱其為「自首日起即建於敬畏之上嘅清真寺」（討白9:108）。先知 ﷺ 話，凡喺屋企淨身，然後前往庫巴喺嗰度禮拜者，獲得一次副朝嘅回賜。`, ja: `預言者 ﷺ は、ヒジュラ暦元年のラビー・アルアウワル月、ヒジュラの途上での滞在中、マディーナのすぐ外にクバー・モスクを建てられた。アッラーはクルアーンの中でこれを「初日から敬虔さの上に築かれたモスク」と述べておられる（アッ・タウバ 9:108）。預言者 ﷺ は、家で身を清めた後クバーに行きそこで礼拝する者は、ウムラの報奨を得ると仰せられた。`, ru: `Пророк ﷺ построил мечеть Куба на окраине Медины в месяце раби аль-авваль первого года хиджры, во время остановки в пути хиджры. Аллах описывает её в Коране как «мечеть, основанную на богобоязненности с первого дня» (ат-Тауба 9:108). Пророк ﷺ сказал, что тот, кто очистится дома, затем пойдёт в Кубу и помолится там, получит награду умры.`, es: `El Profeta ﷺ construyó la Mezquita de Quba justo a las afueras de Medina en Rabi al-Awwal del primer año de la Hégira, durante su parada en el camino de la Hégira. Al-lah la describe en el Corán como «una mezquita fundada sobre la piedad desde el primer día» (al-Tawba 9:108). El Profeta ﷺ dijo que quien se purifica en casa y luego va a Quba y ora allí recibe la recompensa de una 'umrah.`, ko: `예언자 ﷺ 께서는 히즈라 원년 라비 알아우왈월, 히즈라 여정 중 잠시 머무르실 때 마디나 바로 외곽에 쿠바 모스크를 건립하셨다. 알라께서는 꾸란에서 이를 "첫날부터 경건함 위에 세워진 모스크"라고 묘사하신다(앗타우바 9:108). 예언자 ﷺ 께서는 집에서 몸을 정화한 뒤 쿠바로 가서 그곳에서 기도하는 자는 움라의 보상을 받는다고 말씀하셨다.`, ta: `நபி ﷺ ஹிஜ்ரி முதலாம் ஆண்டு ரபீவுல் அவ்வல் மாதத்தில், ஹிஜ்ரா பயணத்தின் இடைநிறுத்தத்தின்போது, மதீனாவின் புறநகரில் குபா மசூதியைக் கட்டினார். அல்லாஹ் இதை குர்ஆனில் "முதல் நாளிலிருந்தே தக்வாவின் அடிப்படையில் நிறுவப்பட்ட மசூதி" என்று விவரிக்கிறான் (அத்-தவ்பா 9:108). நபி ﷺ கூறினார், வீட்டில் தூய்மையாகி, பின்னர் குபாவுக்குச் சென்று அங்கு தொழுபவர் ஒரு உம்ராவின் நற்கூலியைப் பெறுவார்.`, si: `නබි ﷺ තුමා හිජ්රි වර්ෂයේ පළමු වසරේ රබීඋල් අව්වල් මාසයේදී, හිජ්රා ගමනේදී නවතින විට මදීනාවෙන් පිටත කුබා මස්ජිදය ඉදි කළහ. අල්ලාහ් අල් කුර්ආනයේ එය "පළමු දින සිටම භක්තිය මත පදනම් වූ මස්ජිදයක්" ලෙස විස්තර කරයි (අත්-තව්බා 9:108). නබි ﷺ තුමා පැවසුවේ නිවසේදී පිරිසිදු වී, පසුව කුබාවට ගොස් එහි නමස්කාර කරන ඕනෑම කෙනෙකුට උම්රාහ්වක ප්‍රතිඵලය ලැබෙන බවයි.` },
  hist_p2: { en: `Days later he began the Masjid al-Nabawi in the centre of Madinah, carrying its mud bricks himself. It was a plain space of palm-trunk pillars and a palm-frond roof, with a raised platform (al-Suffa) for the poor companions who lived in it. From this simple structure came the model of every masjid built since: a courtyard, a covered prayer hall, a mihrab indicating the qiblah, a minbar for the khutbah, and open access for every Muslim.`, ms: `Beberapa hari kemudian baginda memulakan pembinaan Masjid al-Nabawi di tengah-tengah Madinah, membawa batu-bata tanah liatnya sendiri. Ia hanyalah ruang yang ringkas dengan tiang-tiang batang kurma dan bumbung daripada pelepah kurma, dengan sebuah pelantar tinggi (al-Suffah) untuk para sahabat yang miskin yang tinggal di situ. Daripada struktur ringkas inilah terbentuk model setiap masjid yang dibina sejak itu: sebuah halaman, dewan solat yang beratap, sebuah mihrab menunjukkan kiblat, sebuah mimbar untuk khutbah, dan akses terbuka untuk setiap Muslim.`, tur: `Günler sonra Medine'nin merkezinde Mescid-i Nebevî'yi inşa etmeye başladı ve kerpiçlerini bizzat kendisi taşıdı. Hurma gövdesi sütunları ve hurma yaprağı çatısıyla sade bir mekândı; orada yaşayan yoksul sahabîler için yüksek bir platform (Suffe) bulunuyordu. Bu sade yapıdan, o günden bu yana inşa edilen her mescidin modeli doğdu: bir avlu, kapalı bir namaz salonu, kıbleyi gösteren bir mihrap, hutbe için bir minber ve her Müslümana açık erişim.`, urd: `چند دن بعد باغ ﷺ نے مدینہ کے وسط میں مسجدِ نبوی کی تعمیر شروع کی اور خود اپنے ہاتھوں سے مٹی کی اینٹیں اٹھائیں۔ یہ کھجور کے تنوں کے ستونوں اور کھجور کی شاخوں کی چھت والی ایک سادہ جگہ تھی، جس میں وہاں رہنے والے غریب صحابہ کے لیے ایک اونچا چبوترہ (الصفہ) تھا۔ اسی سادہ ڈھانچے سے اُس نمونے کی بنیاد پڑی جس پر آج تک ہر مسجد بنائی جاتی ہے: ایک صحن، ایک ڈھکا ہوا نماز گاہ، قبلہ کی نشاندہی کرنے والا محراب، خطبے کے لیے منبر، اور ہر مسلمان کے لیے کھلی رسائی۔`, ben: `কয়েকদিন পর নবী ﷺ মদিনার কেন্দ্রে মসজিদে নববী নির্মাণ শুরু করেন এবং নিজ হাতে কাদামাটির ইট বহন করেন। এটি ছিল খেজুর গাছের কাণ্ডের খুঁটি এবং খেজুরপাতার ছাদবিশিষ্ট একটি সাধারণ স্থান, যেখানে বসবাসকারী দরিদ্র সাহাবাদের জন্য একটি উঁচু মঞ্চ (আস-সুফফা) ছিল। এই সাধারণ কাঠামো থেকেই এরপর নির্মিত প্রতিটি মসজিদের আদর্শ তৈরি হয়: একটি আঙিনা, একটি ছাদযুক্ত নামাজ কক্ষ, কিবলা নির্দেশক একটি মিহরাব, খুতবার জন্য একটি মিম্বার, এবং প্রতিটি মুসলমানের জন্য উন্মুক্ত প্রবেশাধিকার।`, fas: `چند روز بعد پیامبر ﷺ ساخت مسجد نبوی را در مرکز مدینه آغاز کرد و خود خشت‌های گلی آن را حمل می‌کرد. جایی ساده با ستون‌هایی از تنه نخل و سقفی از برگ نخل، با سکویی مرتفع (الصفه) برای اصحاب فقیری که در آن زندگی می‌کردند. از این سازه ساده، الگوی هر مسجدی که از آن پس ساخته شد پدید آمد: صحنی، سالنی سرپوشیده برای نماز، محرابی نشان‌دهنده قبله، منبری برای خطبه، و دسترسی آزاد برای هر مسلمان.`, zh: `数日后，先知 ﷺ 亲自搬运泥砖，开始在麦地那中心兴建先知清真寺。那是一处简朴之地，以椰枣树干为柱、椰枣叶为顶，并设有一座高台（苏法）供居住于此的贫苦门弟子使用。此后所建的每座清真寺，其范式皆源自这简朴的结构：一个庭院、一间有顶的礼拜厅、一处指示朝向的米哈拉布、一座供呼图白用的敏拜尔，以及向每位穆斯林开放的通道。`, yue: `幾日後，先知 ﷺ 親自搬運泥磚，開始喺麥地那中心興建先知清真寺。嗰係一處簡樸之地，以椰棗樹幹為柱、椰棗葉為頂，並設有一座高台（蘇法）供居住喺呢度嘅貧苦門弟子使用。此後所建嘅每座清真寺，其範式皆源自呢個簡樸嘅結構：一個庭院、一間有頂嘅禮拜廳、一處指示朝向嘅米哈拉布、一座供呼圖白用嘅敏拜爾，以及向每位穆斯林開放嘅通道。`, ja: `数日後、預言者 ﷺ はマディーナの中心にマスジド・アン・ナバウィーの建設を始め、自らその泥レンガを運ばれた。それはナツメヤシの幹の柱とナツメヤシの葉の屋根から成る質素な空間で、そこに住む貧しい教友たちのための高台（アッ・スッファ）が設けられていた。この質素な建物から、以後建てられるすべてのモスクの型が生まれた。中庭、屋根付きの礼拝堂、キブラを示すミフラーブ、フトバのためのミンバル、そしてすべてのムスリムへの開かれた出入り口である。`, ru: `Через несколько дней он начал строительство мечети ан-Набави в центре Медины, сам нося глиняные кирпичи. Это было простое пространство с колоннами из пальмовых стволов и крышей из пальмовых листьев, с возвышенной платформой (ас-Суффа) для бедных сподвижников, живших там. Из этой простой постройки возникла модель каждой мечети, построенной с тех пор: двор, крытый молитвенный зал, михраб, указывающий киблу, минбар для хутбы и открытый доступ для каждого мусульманина.`, es: `Días después comenzó la Mezquita del Profeta en el centro de Medina, cargando él mismo sus ladrillos de barro. Era un espacio sencillo de columnas de troncos de palmera y techo de hojas de palmera, con una plataforma elevada (al-Suffa) para los compañeros pobres que vivían allí. De esta estructura sencilla surgió el modelo de toda mezquita construida desde entonces: un patio, una sala de oración cubierta, un mihrab que indica la qiblah, un minbar para la khutbah, y acceso abierto para todo musulmán.`, ko: `며칠 뒤 예언자 ﷺ 께서는 마디나 중심부에 예언자 모스크(마스지드 안나바위) 건립을 시작하시며 직접 진흙 벽돌을 나르셨다. 그것은 야자수 기둥과 야자 잎 지붕으로 이루어진 소박한 공간으로, 그곳에 거주하던 가난한 교우들을 위한 높은 단(앗숫파)이 있었다. 이 소박한 구조에서 이후 지어진 모든 모스크의 모델이 나왔다: 안뜰, 지붕이 있는 예배당, 끼블라를 가리키는 미흐랍, 쿠트바를 위한 민바르, 그리고 모든 무슬림에게 열린 출입구.`, ta: `சில நாட்களுக்குப் பிறகு நபி ﷺ மதீனாவின் மையத்தில் மஸ்ஜிதுந் நபவீயைத் தொடங்கினார், தானே சேற்று செங்கற்களைச் சுமந்தார். அது பேரீச்சை மரத் தண்டு தூண்களும் பேரீச்சை ஓலை கூரையும் கொண்ட எளிய இடமாக இருந்தது, அங்கு வாழ்ந்த ஏழை தோழர்களுக்காக ஒரு உயர்ந்த தளம் (அஸ்-சுஃப்பா) இருந்தது. இந்த எளிய கட்டமைப்பிலிருந்தே பின்னர் கட்டப்பட்ட ஒவ்வொரு மசூதியின் மாதிரியும் உருவானது: ஒரு முற்றம், மேல்கூரையிட்ட தொழுகை மண்டபம், கிப்லாவைக் காட்டும் மிஹ்ராப், குத்பாவுக்கான மிம்பர், மற்றும் ஒவ்வொரு முஸ்லிமுக்கும் திறந்த அணுகல்.`, si: `දින කිහිපයකට පසු නබි ﷺ තුමා මදීනාවේ මධ්‍යයේ මස්ජිදුන් නබවී ඉදිකිරීම ආරම්භ කළහ, තමන්ම මැටි ගඩොල් ගෙන ගියහ. එය රටිඳුරු කඳන් කණු සහ රටිඳුරු කොළ වහලයක් සහිත සරල ස්ථානයක් විය, එහි වාසය කළ දුප්පත් සගයන් සඳහා උස් වේදිකාවක් (අස්-සුෆ්ෆා) විය. මෙම සරල ව්‍යුහයෙන් එතැන් සිට ඉදිකළ සෑම මස්ජිදයකම ආදර්ශය බිහි විය: මිදුලක්, වහලයක් සහිත නමස්කාරශාලාවක්, කිබ්ලාව දක්වන මිහ්රාබයක්, කුත්බාව සඳහා මින්බරයක්, සහ සෑම මුස්ලිම්වරයෙකුටම විවෘත ප්‍රවේශයක්.` },
  hist_source: { en: `Sources: al-Tawba 9:108; al-Tirmidhi 324 for the Quba merit (Sahl ibn Hunayf); al-Bukhari 428 for the building of al-Nabawi.`, ms: `Sumber: al-Tawbah 9:108; al-Tirmidhi 324 bagi fadhilat Quba (Sahl ibn Hunayf); al-Bukhari 428 bagi pembinaan al-Nabawi.`, tur: `Kaynak: et-Tevbe 9:108; Kuba faziletine dair Tirmizî 324 (Sehl b. Huneyf); Mescid-i Nebevî'nin inşasına dair Buhârî 428.`, urd: `ماخذ: التوبہ ۹:۱۰۸؛ قبا کی فضیلت کے لیے ترمذی ۳۲۴ (سہل بن حنیف)؛ مسجدِ نبوی کی تعمیر کے لیے بخاری ۴۲۸۔`, ben: `উৎস: আত-তাওবা ৯:১০৮; কুবার ফযীলতের জন্য তিরমিযি ৩২৪ (সাহল ইবন হুনাইফ); মসজিদে নববী নির্মাণের জন্য বুখারি ৪২৮।`, fas: `منبع: التوبه ۹:۱۰۸؛ ترمذی ۳۲۴ برای فضیلت قبا (سهل بن حنیف)؛ بخاری ۴۲۸ برای ساخت مسجد نبوی.`, zh: `出处：讨白9:108；库巴之德见提尔米济324（赛赫勒·本·胡奈夫）；先知清真寺之建见布哈里428。`, yue: `出處：討白9:108；庫巴之德見提爾米濟324（賽赫勒·本·胡奈夫）；先知清真寺之建見布哈里428。`, ja: `出典：アッ・タウバ 9:108；クバーの徳についてティルミズィー 324（サフル・イブン・フナイフ）；ナバウィー・モスクの建設についてブハーリー 428。`, ru: `Источники: ат-Тауба 9:108; ат-Тирмизи 324 о достоинстве Кубы (Сахль ибн Хунайф); аль-Бухари 428 о строительстве ан-Набави.`, es: `Fuentes: al-Tawba 9:108; al-Tirmidhi 324 sobre el mérito de Quba (Sahl ibn Hunayf); al-Bukhari 428 sobre la construcción de al-Nabawi.`, ko: `출처: 앗타우바 9:108; 쿠바의 공덕에 관해 알티르미디 324(사흘 이븐 후나이프); 나바위 건립에 관해 알부카리 428.`, ta: `மூலம்: அத்-தவ்பா 9:108; குபாவின் சிறப்புக்கு திர்மிதி 324 (சஹ்ல் இப்னு ஹுனைஃப்); நபவீ கட்டுமானத்திற்கு புகாரி 428.`, si: `මූලාශ්‍රය: අත්-තව්බා 9:108; කුබාහි ගුණය සඳහා තිර්මිදි 324 (සහ්ල් ඉබ්න් හුනයිෆ්); නබවී ඉදිකිරීම සඳහා බුහාරි 428.` },
  enter_h: { en: `On Entering: Right Foot and Du'a`, ms: `Ketika Masuk: Kaki Kanan dan Doa`, tur: `Girerken: Sağ Ayak ve Duâ`, urd: `داخل ہوتے وقت: دائیں پاؤں اور دعا`, ben: `প্রবেশের সময়: ডান পা এবং দোয়া`, fas: `هنگام ورود: پای راست و دعا`, zh: `入寺：右足与祷`, yue: `入寺：右足與禱`, ja: `入るとき：右足と祈願`, ru: `При входе: правая нога и дуа`, es: `Al entrar: pie derecho y du'a`, ko: `들어갈 때: 오른발과 두아`, ta: `நுழையும்போது: வலது கால் மற்றும் பிரார்த்தனை`, si: `ඇතුළු වන විට: දකුණු පාදය සහ දුආව` },
  enter_intro: { en: `Enter with the right foot. Send salat and salam upon the Prophet ﷺ, then recite:`, ms: `Masuklah dengan kaki kanan. Ucapkan selawat dan salam kepada Nabi ﷺ, kemudian bacalah:`, tur: `Sağ ayakla girin. Peygamber'e ﷺ salât ve selâm getirin, ardından şu duâyı okuyun:`, urd: `دائیں پاؤں سے داخل ہوں۔ نبی ﷺ پر درود و سلام بھیجیں، پھر یہ پڑھیں:`, ben: `ডান পা দিয়ে প্রবেশ করুন। নবী ﷺ-এর প্রতি সালাত ও সালাম পাঠ করুন, তারপর এই দোয়া পড়ুন:`, fas: `با پای راست وارد شوید. بر پیامبر ﷺ صلوات و سلام بفرستید، سپس این را بخوانید:`, zh: `以右足入。为先知 ﷺ 送上祝福与平安，然后诵：`, yue: `以右足入。為先知 ﷺ 送上祝福與平安，然後誦：`, ja: `右足で入り、預言者 ﷺ にサラートとサラームを送り、次を唱えなさい：`, ru: `Входи с правой ноги. Прочти салят и салам за Пророка ﷺ, затем произнеси:`, es: `Entra con el pie derecho. Envía salat y salam al Profeta ﷺ, luego recita:`, ko: `오른발로 들어간다. 예언자 ﷺ 께 살라와 살람을 보낸 뒤 다음을 낭송하라:`, ta: `வலது காலால் நுழையுங்கள். நபி ﷺ மீது ஸலவாத் மற்றும் ஸலாம் அனுப்பி, பின்னர் இதை ஓதுங்கள்:`, si: `දකුණු පාදයෙන් ඇතුළු වන්න. නබි ﷺ තුමා වෙත සලාවත් හා සලාම් යවා, පසුව මෙය කියවන්න:` },
  enter_translit: { en: `Allahumma-ftah li abwaba rahmatik.`, ms: `Allahumma-ftah li abwaba rahmatik.`, tur: `Allāhümme-ftah lî ebvâbe rahmetik.`, urd: `اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ۔`, ben: `আল্লাহুম্মাফতাহ লি আবওয়াবা রাহমাতিক।`, fas: `اللهم افتح لی أبواب رحمتک.`, zh: `安拉呼曼·福塔赫·利·艾布瓦巴·拉赫马提克。`, yue: `安拉呼曼·福塔赫·利·艾布瓦巴·拉赫馬提克。`, ja: `アッラーフンマ・フタフ・リー・アブワーバ・ラフマティク。`, ru: `Аллахумма-фтах ли абваба рахматик.`, es: `Al-lahumma-ftah li abwaba rahmatik.`, ko: `알라훔마 프타흐 리 아브와바 라흐마티크.`, ta: `அல்லாஹும்ம ஃப்தஹ் லீ அப்வாப ரஹ்மதிக்.`, si: `අල්ලාහුම්ම ෆ්තහ් ලී අබ්වාබ රහ්මතික්.` },
  enter_meaning: { en: `O Allah, open for me the gates of Your mercy.`, ms: `Ya Allah, bukakanlah untukku pintu-pintu rahmat-Mu.`, tur: `Allah'ım, bana rahmetinin kapılarını aç.`, urd: `اے اللہ! میرے لیے اپنی رحمت کے دروازے کھول دے۔`, ben: `হে আল্লাহ! আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন।`, fas: `خدایا! درهای رحمت خود را برای من بگشا.`, zh: `真主啊！求你为我打开你慈悯的门户。`, yue: `真主啊！求你為我打開你慈憫嘅門戶。`, ja: `アッラーよ、われのために御身の慈悲の門をお開きください。`, ru: `О Аллах! Открой для меня врата Твоей милости.`, es: `¡Oh Al-lah! Ábreme las puertas de Tu misericordia.`, ko: `오 알라시여! 저를 위해 당신의 자비의 문을 열어 주소서.`, ta: `யா அல்லாஹ்! எனக்காக உன் அருளின் வாசல்களைத் திற.`, si: `අහෝ අල්ලාහ්! මා වෙනුවෙන් ඔබේ කරුණාවේ දොරටු විවෘත කරන්න.` },
  enter_source: { en: `Source: Muslim 713 (Abu Humayd or Abu Usayd al-Sa'idi).`, ms: `Sumber: Muslim 713 (Abu Humayd atau Abu Usayd al-Sa'idi).`, tur: `Kaynak: Müslim 713 (Ebû Humeyd veya Ebû Üseyd el-Sâidî).`, urd: `ماخذ: مسلم ۷۱۳ (ابو حمید یا ابو اسید الساعدی)۔`, ben: `উৎস: মুসলিম ৭১৩ (আবু হুমাইদ অথবা আবু উসাইদ আস-সাইদি)।`, fas: `منبع: مسلم ۷۱۳ (ابوحمید یا ابواسید ساعدی).`, zh: `出处：穆斯林713（艾布·胡迈德或艾布·奥赛德·萨仪迪）。`, yue: `出處：穆斯林713（艾布·胡邁德或艾布·奧賽德·薩儀迪）。`, ja: `出典：ムスリム 713（アブー・フマイドまたはアブー・ウサイド・アッサーイディー）。`, ru: `Источник: Муслим 713 (Абу Хумайд или Абу Усайд ас-Саиди).`, es: `Fuente: Muslim 713 (Abu Humayd o Abu Usayd al-Sa'idi).`, ko: `출처: 무슬림 713(아부 후마이드 또는 아부 우사이드 알사이디).`, ta: `மூலம்: முஸ்லிம் 713 (அபூ ஹுமைத் அல்லது அபூ உசைத் அஸ்-ஸாயிதீ).`, si: `මූලාශ්‍රය: මුස්ලිම් 713 (අබූ හුමයිද් හෝ අබූ උසයිද් අස්-සාඉදී).` },
  tahiyya_h: { en: `Tahiyyat al-Masjid: Two Rakat Before Sitting`, ms: `Tahiyyat al-Masjid: Dua Rakaat Sebelum Duduk`, tur: `Tahiyyetü'l-Mescid: Oturmadan Önce İki Rekât`, urd: `تحیۃ المسجد: بیٹھنے سے پہلے دو رکعت`, ben: `তাহিয়্যাতুল মসজিদ: বসার আগে দুই রাকাত`, fas: `تحیة المسجد: دو رکعت پیش از نشستن`, zh: `清真寺致敬拜：坐下前的两拜`, yue: `清真寺致敬拜：坐低前嘅兩拜`, ja: `タヒーヤト・アル・マスジド：座る前の二ラクアト`, ru: `Тахийят аль-масджид: два ракаата перед тем, как сесть`, es: `Tahiyyat al-Masjid: dos rakat antes de sentarse`, ko: `타히야트 알마스지드: 앉기 전의 두 라카`, ta: `தஹிய்யத் அல்-மஸ்ஜித்: அமருவதற்கு முன் இரண்டு ரக்அத்`, si: `තහිය්‍යතුල් මස්ජිද්: වාඩි වීමට පෙර රකආත් දෙකක්` },
  tahiyya_p1: { en: `The Prophet ﷺ said: "When any of you enters the masjid, let him not sit until he has prayed two rakat." This is tahiyyat al-masjid, the greeting of the masjid, and it is sunnah muakkadah in the Shafi'i, Maliki and Hanbali schools, and mustahabb in the Hanafi school.`, ms: `Nabi ﷺ bersabda: "Apabila mana-mana antara kamu memasuki masjid, janganlah dia duduk sehingga dia solat dua rakaat." Inilah tahiyyat al-masjid, iaitu penghormatan kepada masjid, dan ia adalah sunnah muakkadah dalam mazhab Syafi'i, Maliki dan Hanbali, serta mustahab dalam mazhab Hanafi.`, tur: `Peygamber ﷺ şöyle buyurdu: "Sizden biriniz mescide girdiğinde, iki rekât namaz kılmadan oturmasın." Bu, mescidin selamlanması olan tahiyyetü'l-mescid'dir; Şâfiî, Mâlikî ve Hanbelî mezheplerinde müekked sünnet, Hanefî mezhebinde ise müstehaptır.`, urd: `نبی ﷺ نے فرمایا: "جب تم میں سے کوئی مسجد میں داخل ہو تو دو رکعت نماز پڑھے بغیر نہ بیٹھے۔" یہی تحیۃ المسجد، یعنی مسجد کی تعظیم ہے، اور یہ شافعی، مالکی اور حنبلی مسالک میں سنت موکدہ ہے، جبکہ حنفی مسلک میں مستحب ہے۔`, ben: `নবী ﷺ বলেছেন: "তোমাদের কেউ মসজিদে প্রবেশ করলে দুই রাকাত নামাজ না পড়া পর্যন্ত বসবে না।" এটিই তাহিয়্যাতুল মসজিদ, অর্থাৎ মসজিদের প্রতি সম্মান প্রদর্শন, এবং এটি শাফিঈ, মালিকী ও হাম্বলী মাযহাবে সুন্নাতে মুআক্কাদাহ, আর হানাফী মাযহাবে মুস্তাহাব।`, fas: `پیامبر ﷺ فرمود: «هرگاه یکی از شما وارد مسجد شد، ننشیند تا دو رکعت نماز بگزارد.» این همان تحیة المسجد، یعنی سلام به مسجد است، و در مذاهب شافعی، مالکی و حنبلی سنت مؤکد، و در مذهب حنفی مستحب است.`, zh: `先知 ﷺ 说：「你们中任何人进入清真寺，须先礼两拜，然后方可坐下。」此即「清真寺致敬拜」，在沙斐仪、马立克及罕百里学派中为强调圣行，在哈乃斐学派中为可嘉之举。`, yue: `先知 ﷺ 話：「你哋中任何人入清真寺，須先禮兩拜，然後先可以坐低。」呢個即係「清真寺致敬拜」，喺沙斐儀、馬立克及罕百里學派中為強調聖行，喺哈乃斐學派中為可嘉之舉。`, ja: `預言者 ﷺ は仰せられた。「あなた方の誰かがモスクに入るとき、二ラクアトの礼拝をするまでは座ってはならない。」これがタヒーヤト・アル・マスジド、すなわちモスクへの挨拶であり、シャーフィイー派、マーリキー派、ハンバリー派では強調されたスンナであり、ハナフィー派では推奨行為である。`, ru: `Пророк ﷺ сказал: «Когда кто-либо из вас входит в мечеть, пусть не садится, пока не совершит два ракаата». Это тахийят аль-масджид, приветствие мечети, и это сунна муаккада в шафиитском, маликитском и ханбалитском мазхабах, и мустахабб в ханафитском мазхабе.`, es: `El Profeta ﷺ dijo: «Cuando alguno de vosotros entre en la mezquita, que no se siente hasta haber orado dos rakat». Esto es tahiyyat al-masjid, el saludo a la mezquita, y es sunnah muakkadah en las escuelas shafi'i, maliki y hanbali, y mustahabb en la escuela hanafi.`, ko: `예언자 ﷺ 께서 말씀하셨다: "너희 중 누구든 모스크에 들어가면 두 라카를 기도하기 전까지는 앉지 말라." 이것이 모스크에 대한 인사인 타히야트 알마스지드이며, 샤피이, 말리키, 한발리 학파에서는 순나 무아카다이고 하나피 학파에서는 무스타합이다.`, ta: `நபி ﷺ கூறினார்: "உங்களில் யாராவது மசூதிக்குள் நுழைந்தால், இரண்டு ரக்அத் தொழும் வரை அமராமல் இருக்கட்டும்." இதுவே தஹிய்யத் அல்-மஸ்ஜித், மசூதிக்கான வணக்கம், இது ஷாஃபிஈ, மாலிகீ, ஹன்பலீ மத்ஹப்களில் ஸுன்னத் முஅக்கதா, ஹனஃபீ மத்ஹபில் முஸ்தஹப் ஆகும்.`, si: `නබි ﷺ තුමා පැවසුවේ: "ඔබ අතුරින් කවරෙකු මස්ජිදයට ඇතුළු වුවද, ඔහු රකආත් දෙකක් නමස්කාර කරන තෙක් වාඩි නොවිය යුතුය." මෙය තහිය්‍යතුල් මස්ජිද්, එනම් මස්ජිදයට ගෞරව දැක්වීමයි, එය ෂාෆිඊ, මාලිකී සහ හන්බලී මාසිබයන්හි සුන්නත් මුඅක්කදා වන අතර හනෆී මාසිබයේ මුස්තහබ් වේ.` },
  tahiyya_p2: { en: `It is dropped in specific cases: if the congregation is already praying the fard, if entering at a forbidden time (sunrise, zenith, sunset) for the strict view, or if entering only to pass through. If the iqamah is called, you join the fard directly; the fard itself suffices for the greeting.`, ms: `Ia digugurkan dalam kes-kes tertentu: jika jemaah sudah pun mendirikan solat fardu, jika memasuki pada waktu yang dilarang (terbit matahari, tergelincir, terbenam matahari) menurut pandangan yang ketat, atau jika masuk hanya untuk melalui sahaja. Jika iqamah sudah dilaungkan, kamu terus menyertai solat fardu; solat fardu itu sendiri sudah memadai sebagai penghormatan.`, tur: `Belirli durumlarda düşer: cemaat zaten farzı kılıyorsa, katı görüşe göre yasaklanmış bir vakitte (güneş doğarken, tam tepedeyken, batarken) girildiyse, veya sadece geçmek için girildiyse. İkamet getirilmişse doğrudan farza katılırsınız; farzın kendisi selamlama yerine geçer.`, urd: `یہ مخصوص حالات میں ساقط ہو جاتی ہے: اگر جماعت پہلے سے فرض ادا کر رہی ہو، اگر سخت رائے کے مطابق ممنوعہ وقت (طلوعِ آفتاب، نصف النہار، غروبِ آفتاب) میں داخل ہوں، یا اگر صرف گزرنے کے لیے داخل ہوں۔ اگر اقامت ہو چکی ہو تو براہِ راست فرض میں شامل ہو جائیں؛ خود فرض ہی تحیۃ المسجد کے لیے کافی ہے۔`, ben: `নির্দিষ্ট ক্ষেত্রে এটি রহিত হয়ে যায়: যদি জামাত ইতোমধ্যে ফরজ নামাজ আদায় করে থাকে, কঠোর মতানুসারে নিষিদ্ধ সময়ে (সূর্যোদয়, মধ্যাহ্ন, সূর্যাস্ত) প্রবেশ করলে, অথবা শুধু চলাচলের জন্য প্রবেশ করলে। ইকামত দেওয়া হলে সরাসরি ফরজে যোগ দিন; ফরজ নামাজই তাহিয়্যার জন্য যথেষ্ট।`, fas: `در موارد خاصی ساقط می‌شود: اگر جماعت هم‌اکنون فریضه را می‌گزارد، اگر بنا بر نظر سخت‌گیرانه در وقت ممنوع (طلوع، ظهر، غروب) وارد شود، یا اگر تنها برای عبور وارد شود. اگر اقامه گفته شد، مستقیماً به فریضه بپیوندید؛ خود فریضه برای تحیه کافی است.`, zh: `在特定情况下可免除：若会众已在礼主命拜、若依严格观点于禁止时段（日出、正午、日落）入寺、或仅为路过而入寺。若已喊宣礼词（伊卡麻），应直接加入主命拜；主命拜本身即可代替致敬拜。`, yue: `喺特定情況下可免除：若會眾已經喺禮主命拜、若依嚴格觀點喺禁止時段（日出、正午、日落）入寺、或只係為咗路過而入寺。若已經喊宣禮詞（伊卡瑪），應直接加入主命拜；主命拜本身即可代替致敬拜。`, ja: `特定の場合には省略される：会衆がすでにファルドを礼拝している場合、厳格な見解による禁止時間帯（日の出、正中、日没）に入る場合、あるいは単に通り過ぎるために入る場合である。イカーマが唱えられたなら直接ファルドに加わればよく、ファルド自体が挨拶として十分である。`, ru: `Это опускается в определённых случаях: если джамаат уже совершает фард, если вход происходит в запретное время (восход, зенит, закат) согласно строгому мнению, или если вход только для того, чтобы пройти. Если объявлена икама, вы сразу присоединяетесь к фарду; сам фард служит приветствием.`, es: `Se omite en casos específicos: si la congregación ya está orando el fard, si se entra en un momento prohibido (salida del sol, cenit, puesta del sol) según la opinión estricta, o si se entra solo para pasar. Si se llama al iqamah, te unes directamente al fard; el propio fard basta como saludo.`, ko: `특정 상황에서는 생략된다: 회중이 이미 파르드를 예배하고 있는 경우, 엄격한 견해에 따라 금지된 시간(일출, 정오, 일몰)에 들어가는 경우, 또는 단지 통과하기 위해 들어가는 경우이다. 이까마가 외쳐지면 곧바로 파르드에 합류하면 되며, 파르드 자체가 인사를 대신한다.`, ta: `குறிப்பிட்ட சூழல்களில் இது தவிர்க்கப்படுகிறது: ஜமாஅத் ஏற்கனவே ஃபர்ளு தொழுது கொண்டிருந்தால், கடுமையான கருத்துப்படி தடைசெய்யப்பட்ட நேரத்தில் (சூரிய உதயம், நடுவான், சூரிய அஸ்தமனம்) நுழைந்தால், அல்லது வெறுமனே கடந்து செல்ல மட்டும் நுழைந்தால். இகாமத் சொல்லப்பட்டால், நேரடியாக ஃபர்ளில் இணையுங்கள்; ஃபர்ளே வணக்கத்திற்குப் போதுமானது.`, si: `විශේෂිත අවස්ථාවලදී එය ඉවත් වේ: ජනසමූහය දැනටමත් ෆර්ළ් නමස්කාරයේ යෙදී සිටින්නේ නම්, දැඩි මතය අනුව තහනම් වේලාවක (හිරු නැඟීම, මධ්‍යාහ්නය, හිරු බැසීම) ඇතුළු වන්නේ නම්, හෝ හුදෙක් ගමන් කිරීමට පමණක් ඇතුළු වන්නේ නම්. ඉකාමා කියනු ලැබුවහොත්, ඔබ කෙලින්ම ෆර්ළ්හි එකතු වන්න; ගෞරව දැක්වීම සඳහා ෆර්ළ් එකම ප්‍රමාණවත්ය.` },
  tahiyya_source: { en: `Source: al-Bukhari 444, Muslim 714 (Abu Qatada).`, ms: `Sumber: al-Bukhari 444, Muslim 714 (Abu Qatadah).`, tur: `Kaynak: Buhârî 444, Müslim 714 (Ebû Katâde).`, urd: `ماخذ: بخاری ۴۴۴، مسلم ۷۱۴ (ابو قتادہ)۔`, ben: `উৎস: বুখারি ৪৪৪, মুসলিম ৭১৪ (আবু কাতাদা)।`, fas: `منبع: بخاری ۴۴۴، مسلم ۷۱۴ (ابوقتاده).`, zh: `出处：布哈里444，穆斯林714（艾布·卡塔达）。`, yue: `出處：布哈里444，穆斯林714（艾布·卡塔達）。`, ja: `出典：ブハーリー 444、ムスリム 714（アブー・カターダ）。`, ru: `Источник: аль-Бухари 444, Муслим 714 (Абу Катада).`, es: `Fuente: al-Bukhari 444, Muslim 714 (Abu Qatada).`, ko: `출처: 알부카리 444, 무슬림 714(아부 카타다).`, ta: `மூலம்: புகாரி 444, முஸ்லிம் 714 (அபூ கத்தாதா).`, si: `මූලාශ්‍රය: බුහාරි 444, මුස්ලිම් 714 (අබූ කතාදා).` },
  leave_h: { en: `On Leaving: Left Foot and Du'a`, ms: `Ketika Keluar: Kaki Kiri dan Doa`, tur: `Çıkarken: Sol Ayak ve Duâ`, urd: `نکلتے وقت: بائیں پاؤں اور دعا`, ben: `বের হওয়ার সময়: বাম পা এবং দোয়া`, fas: `هنگام خروج: پای چپ و دعا`, zh: `出寺：左足与祷`, yue: `出寺：左足與禱`, ja: `出るとき：左足と祈願`, ru: `При выходе: левая нога и дуа`, es: `Al salir: pie izquierdo y du'a`, ko: `나갈 때: 왼발과 두아`, ta: `வெளியேறும்போது: இடது கால் மற்றும் பிரார்த்தனை`, si: `පිටව යන විට: වම් පාදය සහ දුආව` },
  leave_intro: { en: `Leave with the left foot. Send salat and salam upon the Prophet ﷺ, then recite:`, ms: `Keluarlah dengan kaki kiri. Ucapkan selawat dan salam kepada Nabi ﷺ, kemudian bacalah:`, tur: `Sol ayakla çıkın. Peygamber'e ﷺ salât ve selâm getirin, ardından şu duâyı okuyun:`, urd: `بائیں پاؤں سے نکلیں۔ نبی ﷺ پر درود و سلام بھیجیں، پھر یہ پڑھیں:`, ben: `বাম পা দিয়ে বের হন। নবী ﷺ-এর প্রতি সালাত ও সালাম পাঠ করুন, তারপর এই দোয়া পড়ুন:`, fas: `با پای چپ خارج شوید. بر پیامبر ﷺ صلوات و سلام بفرستید، سپس این را بخوانید:`, zh: `以左足出。为先知 ﷺ 送上祝福与平安，然后诵：`, yue: `以左足出。為先知 ﷺ 送上祝福與平安，然後誦：`, ja: `左足で出て、預言者 ﷺ にサラートとサラームを送り、次を唱えなさい：`, ru: `Выходи с левой ноги. Прочти салят и салам за Пророка ﷺ, затем произнеси:`, es: `Sal con el pie izquierdo. Envía salat y salam al Profeta ﷺ, luego recita:`, ko: `왼발로 나간다. 예언자 ﷺ 께 살라와 살람을 보낸 뒤 다음을 낭송하라:`, ta: `இடது காலால் வெளியேறுங்கள். நபி ﷺ மீது ஸலவாத் மற்றும் ஸலாம் அனுப்பி, பின்னர் இதை ஓதுங்கள்:`, si: `වම් පාදයෙන් පිටව යන්න. නබි ﷺ තුමා වෙත සලාවත් හා සලාම් යවා, පසුව මෙය කියවන්න:` },
  leave_translit: { en: `Allahumma inni as'aluka min fadlik.`, ms: `Allahumma inni as'aluka min fadlik.`, tur: `Allāhümme innî es'elüke min fadlik.`, urd: `اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ۔`, ben: `আল্লাহুম্মা ইন্নি আসআলুকা মিন ফাদলিক।`, fas: `اللهم إنّی أسألک من فضلک.`, zh: `安拉呼曼·因尼·艾斯艾鲁卡·敏·法德利卡。`, yue: `安拉呼曼·因尼·艾斯艾魯卡·敏·法德利卡。`, ja: `アッラーフンマ・インニー・アスアルカ・ミン・ファドリカ。`, ru: `Аллахумма инни ас'алука мин фадлик.`, es: `Al-lahumma inni as'aluka min fadlik.`, ko: `알라훔마 인니 아스알루카 민 파들리카.`, ta: `அல்லாஹும்ம இன்னீ அஸ்அலுக மின் ஃபள்லிக்.`, si: `අල්ලාහුම්ම ඉන්නී අස්අලුක මින් ෆද්ලික්.` },
  leave_meaning: { en: `O Allah, I ask You of Your bounty.`, ms: `Ya Allah, aku memohon kepada-Mu daripada kurniaan-Mu.`, tur: `Allah'ım, senin fazlından senden istiyorum.`, urd: `اے اللہ! میں تجھ سے تیرا فضل مانگتا ہوں۔`, ben: `হে আল্লাহ! আমি আপনার অনুগ্রহ থেকে প্রার্থনা করছি।`, fas: `خدایا! از فضل تو مسألت دارم.`, zh: `真主啊！我求你之恩泽。`, yue: `真主啊！我求你之恩澤。`, ja: `アッラーよ、われは御身の恩寵より請い願う。`, ru: `О Аллах! Прошу Тебя из милости Твоей.`, es: `¡Oh Al-lah! Te pido de Tu favor.`, ko: `오 알라시여! 당신의 은혜에서 저에게 베풀어 주소서.`, ta: `யா அல்லாஹ்! உன் அருளிலிருந்து உன்னிடம் கேட்கிறேன்.`, si: `අහෝ අල්ලාහ්! ඔබේ දයාවෙන් ඔබෙන් ඉල්ලමි.` },
  leave_p: { en: `The reversal is deliberate: on entering you ask for mercy (the primary need in worship), on leaving you ask for provision (the primary need in worldly action).`, ms: `Pertukaran ini disengajakan: ketika masuk kamu memohon rahmat (keperluan utama dalam ibadah), ketika keluar kamu memohon rezeki (keperluan utama dalam urusan dunia).`, tur: `Bu değişim kasıtlıdır: girerken rahmet istersin (ibadetin başlıca ihtiyacı), çıkarken rızık istersin (dünya hayatının başlıca ihtiyacı).`, urd: `یہ الٹا ترتیب جان بوجھ کر ہے: داخل ہوتے وقت رحمت طلب کرتے ہو (عبادت کی بنیادی ضرورت)، نکلتے وقت رزق طلب کرتے ہو (دنیوی امور کی بنیادی ضرورت)۔`, ben: `এই পরিবর্তন ইচ্ছাকৃত: প্রবেশ করার সময় আপনি রহমত চান (ইবাদতের প্রধান প্রয়োজন), বের হওয়ার সময় আপনি রিযিক চান (দুনিয়াবি কাজের প্রধান প্রয়োজন)।`, fas: `این جابه‌جایی عمدی است: هنگام ورود، رحمت را طلب می‌کنی (نیازِ اصلی در عبادت)، و هنگام خروج، روزی را طلب می‌کنی (نیازِ اصلی در کارِ دنیوی).`, zh: `此反转乃有意为之：入时求慈悯（拜功之首要），出时求供给（尘世之首要）。`, yue: `此反轉乃有意為之：入時求慈憫（拜功之首要），出時求供給（塵世之首要）。`, ja: `この反転は意図されている：入るときには慈悲を求め（礼拝における第一の必要）、出るときには糧を求める（この世の行動における第一の必要）。`, ru: `Такая перестановка намеренна: при входе просишь милости (главная нужда в поклонении), при выходе, удела (главная нужда в мирских делах).`, es: `La inversión es deliberada: al entrar pides misericordia (la necesidad primera en la adoración), al salir pides provisión (la necesidad primera en la acción mundana).`, ko: `이 반전은 의도된 것이다: 들어갈 때는 자비를 구하고(예배에서 으뜸가는 필요), 나갈 때는 양식을 구한다(세상의 행위에서 으뜸가는 필요).`, ta: `இந்த மாற்றம் வேண்டுமென்றே செய்யப்பட்டது: நுழையும்போது அருளை கேட்கிறீர்கள் (வழிபாட்டின் முதன்மையான தேவை), வெளியேறும்போது வாழ்வாதாரம் கேட்கிறீர்கள் (உலகியல் செயலின் முதன்மையான தேவை).`, si: `මෙම ප්‍රතිලෝමකරණය අරමුණු සහිතය: ඇතුළු වන විට කරුණාව ඉල්ලයි (නමස්කාරයේ මූලික අවශ්‍යතාව), පිටව යන විට රැකවරණය ඉල්ලයි (ලෞකික ක්‍රියාවේ මූලික අවශ්‍යතාව).` },
  leave_source: { en: `Source: Muslim 713.`, ms: `Sumber: Muslim 713.`, tur: `Kaynak: Müslim 713.`, urd: `ماخذ: مسلم ۷۱۳۔`, ben: `উৎস: মুসলিম ৭১৩।`, fas: `منبع: مسلم ۷۱۳.`, zh: `出处：穆斯林 713。`, yue: `出處：穆斯林 713。`, ja: `出典：ムスリム 713。`, ru: `Источник: Муслим 713.`, es: `Fuente: Muslim 713.`, ko: `출처: 무슬림 713.`, ta: `மூலம்: முஸ்லிம் 713.`, si: `මූලාශ්‍රය: මුස්ලිම් 713.` },
  salat_h: { en: `Salat Upon the Prophet ﷺ on Entering and Leaving`, ms: `Selawat ke atas Nabi ﷺ Ketika Masuk dan Keluar`, tur: `Girerken ve Çıkarken Peygamber'e ﷺ Salât Getirmek`, urd: `داخل ہوتے اور نکلتے وقت نبی ﷺ پر درود`, ben: `প্রবেশ ও প্রস্থানের সময় নবী ﷺ-এর প্রতি সালাত`, fas: `صلوات بر پیامبر ﷺ هنگام ورود و خروج`, zh: `入寺出寺时向先知 ﷺ 送上祝福`, yue: `入寺出寺時向先知 ﷺ 送上祝福`, ja: `入退時に預言者 ﷺ にサラートを送ること`, ru: `Салят за Пророка ﷺ при входе и выходе`, es: `Salat sobre el Profeta ﷺ al entrar y salir`, ko: `들어가고 나갈 때 예언자 ﷺ 께 살라 낭송`, ta: `நுழையும் மற்றும் வெளியேறும்போது நபி ﷺ மீது ஸலவாத்`, si: `ඇතුළු වන විට හා පිටව යන විට නබි ﷺ තුමා වෙත සලාවත්` },
  salat_p: { en: `Fatimah bint Muhammad ﷺ narrated: "When the Messenger of Allah ﷺ entered the masjid, he would say 'Bismillah wa-s salatu wa-s salamu 'ala rasul-illah, Allahumma-ghfir li dhunubi wa-ftah li abwaba rahmatik.' And when he left he would say the same, replacing 'abwaba rahmatik' with 'abwaba fadlik.'"`, ms: `Fatimah binti Muhammad ﷺ meriwayatkan: "Apabila Rasulullah ﷺ masuk ke masjid, baginda mengucapkan 'Bismillah wa-s salatu wa-s salamu 'ala rasul-illah, Allahumma-ghfir li dhunubi wa-ftah li abwaba rahmatik.' Dan apabila keluar baginda mengucapkan yang sama, dengan menggantikan 'abwaba rahmatik' kepada 'abwaba fadlik.'"`, tur: `Fâtıma binti Muhammed ﷺ rivayet eder: "Rasûlullah ﷺ mescide girdiğinde 'Bismillâh, ves-salâtü ves-selâmü alâ Rasûlillâh, Allâhümme-ğfir lî zünûbî ve-ftah lî ebvâbe rahmetik' derdi. Çıktığında da aynısını söyler, ancak 'ebvâbe rahmetik' yerine 'ebvâbe fadlik' derdi."`, urd: `فاطمہ بنت محمد ﷺ نے روایت کیا: "جب رسول اللہ ﷺ مسجد میں داخل ہوتے تو فرماتے 'بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ۔' اور جب نکلتے تو یہی کہتے مگر 'أبواب رحمتک' کی جگہ 'أبواب فضلک' فرماتے۔"`, ben: `ফাতিমা বিনতে মুহাম্মদ ﷺ বর্ণনা করেন: "রাসূলুল্লাহ ﷺ যখন মসজিদে প্রবেশ করতেন, তিনি বলতেন 'বিসমিল্লাহ ওয়াস সালাতু ওয়াস সালামু আলা রাসূলিল্লাহ, আল্লাহুম্মাগফির লি যুনূবি ওয়াফতাহ লি আবওয়াবা রাহমাতিক।' আর যখন বের হতেন, একই কথা বলতেন, কেবল 'আবওয়াবা রাহমাতিক'-এর জায়গায় 'আবওয়াবা ফাদলিক' বলতেন।"`, fas: `فاطمه بنت محمد ﷺ روایت می‌کند: «هرگاه پیامبر خدا ﷺ به مسجد وارد می‌شد، می‌گفت: بسم الله والصلاة والسلام علی رسول الله، اللهم اغفر لی ذنوبی وافتح لی أبواب رحمتک. و چون خارج می‌شد همان را می‌گفت، جز آنکه به‌جای أبواب رحمتک، أبواب فضلک می‌گفت.»`, zh: `法蒂玛·宾特·穆罕默德 ﷺ 传述：「先知 ﷺ 入寺时诵『奉真主之名，愿祝福与平安归于真主之使者。安拉啊！赦我诸罪，为我开你怜悯之门。』出时诵同一言，惟以『你的恩泽之门』代『你的怜悯之门』。」`, yue: `法蒂瑪·賓特·穆罕默德 ﷺ 傳述：「先知 ﷺ 入寺時誦『奉真主之名，願祝福與平安歸於真主之使者。安拉啊！赦我諸罪，為我開你憐憫之門。』出時誦同一言，惟以『你的恩澤之門』代『你的憐憫之門』。」`, ja: `ファーティマ・ビント・ムハンマド ﷺ が伝える。「アッラーの使徒 ﷺ はモスクに入られると『ビスミッラー、サラートとサラームがアッラーの使徒の上にあれ。アッラーよ、わが罪を赦し、御慈悲の門を開き給え』と唱えられた。出られるときも同じ言葉を唱えられたが、『御慈悲の門』のところを『御恩寵の門』と替えられた。」`, ru: `Фатима бинт Мухаммад ﷺ передала: «Когда Посланник Аллаха ﷺ входил в мечеть, он говорил: „Бисмиллях, ва-с-салату ва-с-саламу 'аля Расулиллях, Аллахумма-гфир ли зунуби ва-фтах ли абваба рахматик“. А когда выходил, говорил то же самое, заменяя „абваба рахматик“ на „абваба фадлик“».`, es: `Fátima bint Muhammad ﷺ narró: «Cuando el Mensajero de Al-lah ﷺ entraba en la masjid, decía 'Bismil-lah, was-salatu was-salamu 'ala rasul-illah, Al-lahumma-ghfir li dhunubi wa-ftah li abwaba rahmatik.' Y al salir decía lo mismo, reemplazando 'abwaba rahmatik' por 'abwaba fadlik.'»`, ko: `파티마 빈트 무함마드 ﷺ 께서 전하시길: "알라의 사도 ﷺ 께서는 모스크에 들어가시면 '비스밀라, 와싸라투 와싸라무 알라 라술릴라, 알라훔마그피르 리 두누비 와프타흐 리 아브와바 라흐마티카'라고 말씀하셨다. 나가실 때도 같은 말씀을 하시되 '아브와바 라흐마티카'를 '아브와바 파들리카'로 바꾸셨다."`, ta: `ஃபாத்திமா பின்த் முஹம்மத் ﷺ அறிவிக்கிறார்: "அல்லாஹ்வின் தூதர் ﷺ மசூதிக்குள் நுழையும்போது 'பிஸ்மில்லாஹ் வஸ் ஸலாது வஸ் ஸலாமு அலா ரஸூலில்லாஹ், அல்லாஹும்மக்ஃபிர் லீ துனூபீ வஃப்தஹ் லீ அப்வாப ரஹ்மதிக்' என்று சொல்வார். வெளியேறும்போதும் அதே சொல்வார், 'அப்வாப ரஹ்மதிக்'-க்கு பதிலாக 'அப்வாப ஃபள்லிக்' என மாற்றி."`, si: `ෆාතිමා බින්ත් මුහම්මද් ﷺ පවසයි: "අල්ලාහ්ගේ දූතයාණන් ﷺ මස්ජිදට ඇතුළු වන විට 'බිස්මිල්ලාහ්, වස්-සලාතු වස්-සලාමු අලා රසූලිල්ලාහ්, අල්ලාහුම්මග්ෆිර් ලී ඡුනූබී වෆ්තහ් ලී අබ්වාබ රහ්මතික්' යැයි කීහ. පිටව යන විටත් එයම කීවෝය, 'අබ්වාබ රහ්මතික්' වෙනුවට 'අබ්වාබ ෆද්ලික්' යැයි වෙනස් කරමින්."` },
  salat_translit: { en: `Allahumma salli 'ala Muhammadin wa 'ala ali Muhammad.`, ms: `Allahumma salli 'ala Muhammadin wa 'ala ali Muhammad.`, tur: `Allāhümme salli alâ Muhammedin ve alâ âli Muhammed.`, urd: `اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ۔`, ben: `আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিন ওয়া আলা আলি মুহাম্মাদ।`, fas: `اللهم صلّ علی محمد و علی آل محمد.`, zh: `安拉呼曼·萨利·阿拉·穆罕默丁·瓦·阿拉·阿利·穆罕默德。`, yue: `安拉呼曼·薩利·阿拉·穆罕默丁·瓦·阿拉·阿利·穆罕默德。`, ja: `アッラーフンマ・サッリ・アラー・ムハンマディン・ワ・アラー・アーリ・ムハンマド。`, ru: `Аллахумма салли 'аля Мухаммадин ва 'аля али Мухаммад.`, es: `Al-lahumma salli 'ala Muhammadin wa 'ala ali Muhammad.`, ko: `알라훔마 살리 알라 무함마딘 와 알라 알리 무함마드.`, ta: `அல்லாஹும்ம ஸல்லி அலா முஹம்மதின் வ அலா ஆலி முஹம்மத்.`, si: `අල්ලාහුම්ම සල්ලි අලා මුහම්මදින් ව අලා ආලි මුහම්මද්.` },
  salat_source: { en: `Source: al-Tirmidhi 314, Ibn Majah 771; Sahih al-Albani.`, ms: `Sumber: al-Tirmidhi 314, Ibn Majah 771; disahihkan oleh al-Albani.`, tur: `Kaynak: Tirmizî 314, İbn Mâce 771; Elbânî sahih dedi.`, urd: `ماخذ: ترمذی ۳۱۴، ابن ماجہ ۷۷۱؛ البانی نے صحیح قرار دیا۔`, ben: `উৎস: তিরমিযি ৩১৪, ইবন মাজাহ ৭৭১; আল-বানি সহীহ বলেছেন।`, fas: `منبع: ترمذی ۳۱۴، ابن ماجه ۷۷۱؛ آلبانی صحیح دانسته است.`, zh: `出处：提尔米济 314、伊本·马哲 771；艾布尼判为正传。`, yue: `出處：提爾米濟 314、伊本·馬哲 771；艾布尼判為正傳。`, ja: `出典：ティルミズィー 314、イブン・マージャ 771；アルバーニーが正伝と評した。`, ru: `Источник: ат-Тирмизи 314, Ибн Маджа 771; аль-Албани оценил как сахих.`, es: `Fuente: al-Tirmidhi 314, Ibn Maja 771; al-Albani lo calificó de sahih.`, ko: `출처: 알티르미디 314, 이븐 마자 771; 알알바니가 사히흐로 평가.`, ta: `மூலம்: திர்மிதி 314, இப்னு மாஜா 771; அல்-அல்பானி ஸஹீஹ் என்று தரப்படுத்தினார்.`, si: `මූලාශ්‍රය: තිර්මිදි 314, ඉබ්න් මාජා 771; අල්-අල්බානි සහීහ් ලෙස තක්සේරු කළහ.` },
  beh_h: { en: `Behaviour Inside the Masjid`, ms: `Adab Di Dalam Masjid`, tur: `Mescit İçindeki Davranış`, urd: `مسجد کے اندر آداب`, ben: `মসজিদের ভেতরে আচরণ`, fas: `آداب رفتار در مسجد`, zh: `寺内举止`, yue: `寺內舉止`, ja: `モスク内での作法`, ru: `Поведение в мечети`, es: `Comportamiento dentro de la mezquita`, ko: `모스크 내에서의 예절`, ta: `மசூதிக்குள் நடத்தை`, si: `මස්ජිදය තුළ හැසිරීම` },
  beh_1: { en: `No commerce. The Prophet ﷺ said: "If you see anyone buying or selling in the masjid, say: 'May Allah not grant profit to your trade.'" (al-Tirmidhi 1321).`, ms: `Tiada urus niaga. Nabi ﷺ bersabda: "Jika kamu melihat sesiapa membeli atau menjual di dalam masjid, katakanlah: 'Semoga Allah tidak memberi keuntungan kepada perniagaanmu.'" (al-Tirmidhi 1321).`, tur: `Ticaret yapılmaz. Peygamber ﷺ şöyle buyurdu: "Mescitte alışveriş yapan birini görürseniz, 'Allah ticaretine kâr vermesin' deyin." (Tirmizî 1321).`, urd: `کوئی تجارت نہیں۔ نبی ﷺ نے فرمایا: "اگر تم کسی کو مسجد میں خرید و فروخت کرتے دیکھو تو کہو: 'اللہ تیری تجارت میں نفع نہ دے۔'" (ترمذی ۱۳۲۱)۔`, ben: `কোনো ব্যবসা নয়। নবী ﷺ বলেছেন: "যদি তোমরা কাউকে মসজিদে ক্রয়-বিক্রয় করতে দেখো, তবে বলো: 'আল্লাহ তোমার ব্যবসায় লাভ না দিন।'" (তিরমিযি ১৩২১)।`, fas: `تجارت ممنوع است. پیامبر ﷺ فرمود: «اگر کسی را دیدید که در مسجد خرید و فروش می‌کند، بگویید: خدا به تجارت تو سودی ندهد.» (ترمذی ۱۳۲۱).`, zh: `禁止经商。先知 ﷺ 说：「若见人在寺内买卖，当说：『愿真主不使你的交易获利。』」（提尔米济1321）。`, yue: `禁止經商。先知 ﷺ 話：「若見人喺寺內買賣，應該話：『願真主唔使你嘅交易獲利。』」（提爾米濟1321）。`, ja: `商取引の禁止。預言者 ﷺ は仰せられた。「モスクで売買をしている者を見たら、『アッラーがあなたの商売に利益を与えませんように』と言いなさい。」（ティルミズィー 1321）。`, ru: `Никакой торговли. Пророк ﷺ сказал: «Если увидите кого-либо, покупающего или продающего в мечети, скажите: „Да не даст Аллах прибыли твоей торговле“» (ат-Тирмизи 1321).`, es: `Sin comercio. El Profeta ﷺ dijo: «Si ves a alguien comprando o vendiendo en la mezquita, di: 'Que Al-lah no conceda beneficio a tu comercio.'» (al-Tirmidhi 1321).`, ko: `상행위 금지. 예언자 ﷺ 께서 말씀하셨다: "모스크에서 사고파는 자를 보거든 '알라께서 네 장사에 이익을 주지 않기를'이라고 말하라." (알티르미디 1321).`, ta: `வணிகம் இல்லை. நபி ﷺ கூறினார்: "மசூதியில் யாராவது வாங்குவதையோ விற்பதையோ கண்டால், 'உன் வர்த்தகத்திற்கு அல்லாஹ் லாபம் தராதிருக்கட்டும்' என்று சொல்லுங்கள்." (திர்மிதி 1321).`, si: `වෙළඳාම් නොකළ යුතුය. නබි ﷺ තුමා පැවසුවේ: "මස්ජිදයේ කිසිවෙකු මිලදී ගැනීම හෝ විකිණීම ඔබ දුටුවහොත්, 'අල්ලාහ් ඔබේ වෙළඳාමට ලාභයක් නොදෙත්වා' යැයි කියන්න." (තිර්මිදි 1321).` },
  beh_2: { en: `No announcing lost items. He ﷺ said: "If any of you hears someone in the masjid announcing a lost item, let him say: 'May Allah not return it to you,' for the masjids were not built for this." (Muslim 568).`, ms: `Tiada pengumuman barang hilang. Baginda ﷺ bersabda: "Jika mana-mana antara kamu mendengar seseorang di dalam masjid mengumumkan barang yang hilang, katakanlah: 'Semoga Allah tidak memulangkannya kepadamu,' kerana masjid-masjid tidak dibina untuk perkara ini." (Muslim 568).`, tur: `Kaybolan eşya ilanı yapılmaz. O ﷺ şöyle buyurdu: "Sizden biriniz mescitte kayıp bir eşyayı ilan eden birini duyarsa, 'Allah onu sana geri vermesin' desin, çünkü mescitler bunun için inşa edilmemiştir." (Müslim 568).`, urd: `گمشدہ اشیاء کا اعلان نہیں۔ آپ ﷺ نے فرمایا: "اگر تم میں سے کوئی مسجد میں کسی کو گمشدہ چیز کا اعلان کرتے سنے تو کہے: 'اللہ تجھے یہ واپس نہ کرے،' کیونکہ مساجد اس مقصد کے لیے نہیں بنائی گئیں۔" (مسلم ۵۶۸)۔`, ben: `হারানো জিনিসের ঘোষণা নয়। তিনি ﷺ বলেছেন: "তোমাদের কেউ যদি মসজিদে কাউকে হারানো জিনিসের ঘোষণা দিতে শোনে, তবে বলুক: 'আল্লাহ তোমাকে তা ফিরিয়ে না দিন,' কারণ মসজিদগুলো এ উদ্দেশ্যে নির্মিত হয়নি।" (মুসলিম ৫৬৮)।`, fas: `اعلام گمشده ممنوع است. او ﷺ فرمود: «اگر یکی از شما بشنود کسی در مسجد گمشده‌ای را اعلام می‌کند، بگوید: خدا آن را به تو بازنگرداند، زیرا مساجد برای این کار ساخته نشده‌اند.» (مسلم ۵۶۸).`, zh: `禁止寻物启事。先知 ﷺ 说：「若你们中有人听见有人在寺内宣布寻找失物，当说：『愿真主不将其归还于你』，因为清真寺不是为此而建。」（穆斯林568）。`, yue: `禁止尋物啟事。先知 ﷺ 話：「若你哋中有人聽見有人喺寺內宣布搵失物，應該話：『願真主唔將其歸還畀你』，因為清真寺唔係為呢個而建。」（穆斯林568）。`, ja: `落とし物の告知の禁止。彼 ﷺ は仰せられた。「あなた方の誰かがモスクで落とし物を告げる者を聞いたら、『アッラーがそれをあなたに返しませんように』と言いなさい。モスクはこのために建てられたのではないからだ。」（ムスリム 568）。`, ru: `Никаких объявлений о пропаже. Он ﷺ сказал: «Если кто-либо из вас услышит в мечети объявляющего о пропаже, пусть скажет: „Да не вернёт её тебе Аллах“, ибо мечети не для этого строились» (Муслим 568).`, es: `Sin anuncios de objetos perdidos. Él ﷺ dijo: «Si alguno de vosotros oye a alguien anunciar un objeto perdido en la mezquita, que diga: 'Que Al-lah no te lo devuelva,' pues las mezquitas no fueron construidas para esto.» (Muslim 568).`, ko: `분실물 공지 금지. 그분 ﷺ 께서 말씀하셨다: "너희 중 누구든 모스크에서 분실물을 알리는 자를 듣거든 '알라께서 그것을 네게 돌려주지 않기를'이라고 말하라. 모스크는 이를 위해 지어진 것이 아니기 때문이다." (무슬림 568).`, ta: `தொலைந்த பொருள் அறிவிப்பு இல்லை. அவர் ﷺ கூறினார்: "மசூதியில் யாராவது தொலைந்த பொருளை அறிவிப்பதை உங்களில் யாராவது கேட்டால், 'அல்லாஹ் அதை உனக்குத் திருப்பித் தராதிருக்கட்டும்' என்று சொல்லட்டும், ஏனெனில் மசூதிகள் இதற்காக கட்டப்படவில்லை." (முஸ்லிம் 568).`, si: `නැති වූ දේ ප්‍රකාශ නොකළ යුතුය. උන් වහන්සේ ﷺ පැවසුවේ: "මස්ජිදයේ කෙනෙකු නැති වූ දෙයක් ප්‍රකාශ කරනු ඔබ අතුරින් කෙනෙකු ඇසුවහොත්, 'අල්ලාහ් එය ඔබට නැවත නොදෙත්වා' යැයි කියත්වා, මන්ද මස්ජිද මේ සඳහා ඉදිකර නොමැති බැවිනි." (මුස්ලිම් 568).` },
  beh_3: { en: `Silence, especially during recitation and the khutbah. The Prophet ﷺ said if you tell your companion during the Jumu'ah khutbah "be quiet," you have committed a wrong (al-Bukhari 934).`, ms: `Berdiam diri, terutamanya semasa bacaan dan khutbah. Nabi ﷺ bersabda jika kamu memberitahu rakanmu semasa khutbah Jumaat "diamlah," kamu telah melakukan suatu kesilapan (al-Bukhari 934).`, tur: `Sessizlik, özellikle kıraat ve hutbe sırasında. Peygamber ﷺ, Cuma hutbesi esnasında arkadaşına "sus" dersen bir hata işlemiş olursun buyurdu (Buhârî 934).`, urd: `خاموشی، خاص طور پر تلاوت اور خطبے کے دوران۔ نبی ﷺ نے فرمایا کہ اگر تم جمعہ کے خطبے کے دوران اپنے ساتھی سے "خاموش رہو" کہو تو تم نے غلطی کی (بخاری ۹۳۴)۔`, ben: `নীরবতা, বিশেষত তিলাওয়াত ও খুতবার সময়। নবী ﷺ বলেছেন, জুমার খুতবার সময় যদি তুমি তোমার সঙ্গীকে "চুপ থাকো" বলো, তবে তুমি ভুল করেছ (বুখারি ৯৩৪)।`, fas: `سکوت، به‌ویژه هنگام تلاوت و خطبه. پیامبر ﷺ فرمود اگر در خطبه جمعه به همراه خود بگویی «ساکت باش»، خطایی مرتکب شده‌ای (بخاری ۹۳۴).`, zh: `保持肃静，特别在诵经与呼图白期间。先知 ﷺ 说，若你在主麻日呼图白期间对同伴说「安静」，你已犯下过失（布哈里934）。`, yue: `保持肅靜，特別喺誦經與呼圖白期間。先知 ﷺ 話，若你喺主麻日呼圖白期間對同伴講「安靜」，你已經犯咗過失（布哈里934）。`, ja: `静粛、特に朗誦とフトバの間。預言者 ﷺ は、ジュムアのフトバの間に隣の者に「静かに」と言えば、それ自体が過ちだと仰せられた（ブハーリー 934）。`, ru: `Тишина, особенно во время чтения Корана и хутбы. Пророк ﷺ сказал, что если ты скажешь своему товарищу во время пятничной хутбы «тише», ты уже совершил проступок (аль-Бухари 934).`, es: `Silencio, especialmente durante la recitación y la khutbah. El Profeta ﷺ dijo que si le dices a tu compañero durante la khutbah del viernes «cállate», has cometido una falta (al-Bukhari 934).`, ko: `침묵, 특히 낭송과 쿠트바 도중. 예언자 ﷺ 께서는 주무아 쿠트바 도중 동료에게 "조용히 해"라고 말하는 것조차 잘못이라고 말씀하셨다 (알부카리 934).`, ta: `மௌனம், குறிப்பாக ஓதுதல் மற்றும் குத்பாவின்போது. நபி ﷺ கூறினார், ஜும்ஆ குத்பாவின்போது உங்கள் தோழரிடம் "அமைதியாக இரு" என்று சொன்னால், நீங்கள் தவறு செய்துவிட்டீர்கள் (புகாரி 934).`, si: `නිශ්ශබ්දතාව, විශේෂයෙන් සජ්ද කිරීම හා කුත්බාව අතරතුර. නබි ﷺ තුමා පැවසුවේ ජුමුආ කුත්බාව අතරතුර ඔබේ මිතුරාට "නිහඬ වන්න" කීවහොත්, ඔබ වරදක් සිදු කර ඇති බවයි (බුහාරි 934).` },
  beh_4: { en: `No walking in front of one who is praying. Move behind them or wait; if unavoidable, the person praying should push gently against you (al-Bukhari 510).`, ms: `Jangan berjalan di hadapan orang yang sedang solat. Beralihlah ke belakangnya atau tunggu; jika tidak dapat dielakkan, orang yang sedang solat itu hendaklah menolakmu dengan lembut (al-Bukhari 510).`, tur: `Namaz kılan birinin önünden geçilmez. Arkasına geçin veya bekleyin; kaçınılmazsa, namaz kılan kişi sizi hafifçe itmelidir (Buhârî 510).`, urd: `نماز پڑھنے والے کے سامنے سے مت گزرو۔ اس کے پیچھے سے جاؤ یا انتظار کرو؛ اگر ناگزیر ہو تو نمازی کو چاہیے کہ نرمی سے تمہیں روکے (بخاری ۵۱۰)۔`, ben: `নামাজরত ব্যক্তির সামনে দিয়ে হাঁটবেন না। তার পেছন দিয়ে যান অথবা অপেক্ষা করুন; অপরিহার্য হলে, নামাজরত ব্যক্তির উচিত আপনাকে নরমভাবে ঠেলে দেওয়া (বুখারি ৫১০)।`, fas: `از جلوی کسی که نماز می‌خواند عبور نکنید. از پشت او بگذرید یا صبر کنید؛ اگر ناگزیر بود، نمازگزار باید به‌آرامی شما را دور کند (بخاری ۵۱۰).`, zh: `不可从正在礼拜者面前经过。应从其身后绕行或等待；若不可避免，礼拜者应轻轻推阻你（布哈里510）。`, yue: `唔可以由正喺度禮拜嘅人面前經過。應該由佢後面繞行或者等待；若唔可以避免，禮拜者應該輕輕推阻你（布哈里510）。`, ja: `礼拝中の者の前を横切ってはならない。後ろに回るか待つこと。避けられない場合、礼拝している者はあなたを軽く押しとどめるべきである（ブハーリー 510）。`, ru: `Не проходи перед молящимся. Обойди сзади или подожди; если это неизбежно, молящийся должен мягко оттолкнуть тебя (аль-Бухари 510).`, es: `No caminar delante de quien está orando. Pasa por detrás o espera; si es inevitable, quien ora debe empujarte suavemente (al-Bukhari 510).`, ko: `기도 중인 사람 앞을 지나가지 말라. 뒤로 돌아가거나 기다려라. 불가피하다면 기도하는 사람이 부드럽게 당신을 막아야 한다 (알부카리 510).`, ta: `தொழுபவர் முன் நடக்க வேண்டாம். அவருக்குப் பின்னால் செல்லுங்கள் அல்லது காத்திருங்கள்; தவிர்க்க முடியாவிட்டால், தொழுபவர் உங்களை மென்மையாகத் தள்ள வேண்டும் (புகாரி 510).`, si: `නමස්කාර කරන කෙනෙකු ඉදිරිපිටින් ඇවිද නොයන්න. ඔහුගේ පිටුපසින් ගමන් කරන්න හෝ රැඳී සිටින්න; වළක්වා ගත නොහැකි නම්, නමස්කාර කරන තැනැත්තා ඔබව මෘදුව තල්ලු කළ යුතුය (බුහාරි 510).` },
  beh_5: { en: `No strong smells. He ﷺ said: "Whoever has eaten garlic or onion, let him keep away from us, and from our masjid." Modern equivalents include strong smoke or heavy perfumes that carry (al-Bukhari 855, Muslim 564).`, ms: `Tiada bau yang kuat. Baginda ﷺ bersabda: "Sesiapa yang telah makan bawang putih atau bawang merah, hendaklah dia menjauhi kami, dan menjauhi masjid kami." Persamaan moden termasuklah asap yang kuat atau minyak wangi yang tebal dan menular (al-Bukhari 855, Muslim 564).`, tur: `Keskin kokular yasaktır. O ﷺ şöyle buyurdu: "Kim sarımsak veya soğan yemişse, bizden ve mescidimizden uzak dursun." Günümüzde buna karşılık gelen örnekler yoğun duman veya yayılan ağır parfümlerdir (Buhârî 855, Müslim 564).`, urd: `تیز بو نہیں۔ آپ ﷺ نے فرمایا: "جو کوئی لہسن یا پیاز کھائے، وہ ہم سے اور ہماری مسجد سے دور رہے۔" جدید مثالوں میں تیز دھواں یا بہت زیادہ پھیلنے والی خوشبو شامل ہے (بخاری ۸۵۵، مسلم ۵۶۴)۔`, ben: `তীব্র গন্ধ নয়। তিনি ﷺ বলেছেন: "যে ব্যক্তি রসুন বা পেঁয়াজ খেয়েছে, সে যেন আমাদের থেকে এবং আমাদের মসজিদ থেকে দূরে থাকে।" আধুনিক সমতুল্য উদাহরণে রয়েছে তীব্র ধোঁয়া বা ভারী সুগন্ধি যা ছড়িয়ে পড়ে (বুখারি ৮৫৫, মুসলিম ৫৬৪)।`, fas: `بوی تند ممنوع است. او ﷺ فرمود: «هر کس سیر یا پیاز خورده، از ما و از مسجد ما دور بماند.» معادل‌های امروزی شامل دود تند یا عطرهای سنگین منتشرشونده است (بخاری ۸۵۵، مسلم ۵۶۴).`, zh: `禁止浓烈气味。先知 ﷺ 说：「凡食大蒜或洋葱者，当远离我们，远离我们的清真寺。」现代对应之物包括浓烟或散发浓烈的香水（布哈里855，穆斯林564）。`, yue: `禁止濃烈氣味。先知 ﷺ 話：「凡食大蒜或洋蔥者，應該遠離我哋，遠離我哋嘅清真寺。」現代對應之物包括濃煙或散發濃烈嘅香水（布哈里855，穆斯林564）。`, ja: `強い臭いの禁止。彼 ﷺ は仰せられた。「ニンニクや玉ねぎを食べた者は、われらと、われらのモスクから遠ざかりなさい。」現代における同様の例には、強い煙や広がる重い香水がある（ブハーリー 855、ムスリム 564）。`, ru: `Никаких резких запахов. Он ﷺ сказал: «Кто съел чеснок или лук, пусть держится подальше от нас и от нашей мечети». Современные эквиваленты включают сильный дым или тяжёлые духи, которые распространяются (аль-Бухари 855, Муслим 564).`, es: `Sin olores fuertes. Él ﷺ dijo: «Quien haya comido ajo o cebolla, que se aleje de nosotros y de nuestra mezquita.» Los equivalentes modernos incluyen humo intenso o perfumes fuertes que se propagan (al-Bukhari 855, Muslim 564).`, ko: `강한 냄새 금지. 그분 ﷺ 께서 말씀하셨다: "마늘이나 양파를 먹은 자는 우리와 우리 모스크에서 멀리 떨어져 있으라." 현대의 예로는 강한 연기나 멀리 퍼지는 진한 향수가 있다 (알부카리 855, 무슬림 564).`, ta: `கடுமையான வாசனை இல்லை. அவர் ﷺ கூறினார்: "பூண்டு அல்லது வெங்காயம் சாப்பிட்டவர், எங்களிடமிருந்தும் எங்கள் மசூதியிலிருந்தும் விலகி இருக்கட்டும்." நவீன ஒப்பீடுகளில் அடர் புகை அல்லது பரவும் கடும் வாசனை திரவியங்கள் அடங்கும் (புகாரி 855, முஸ்லிம் 564).`, si: `තියුණු සුවඳ නොතිබිය යුතුය. උන් වහන්සේ ﷺ පැවසුවේ: "සුදුළූණු හෝ ලූනු අනුභව කළ ඕනෑම කෙනෙකු, අප වෙතින් හා අපේ මස්ජිදයෙන් ඈත් වී සිටිත්වා." නවීන සමානකම්වලට තියුණු දුම හෝ පැතිරෙන බර සුවඳ විලවුන් ඇතුළත් වේ (බුහාරි 855, මුස්ලිම් 564).` },
  beh_6: { en: `Perfume for men is encouraged on Jumu'ah and in general; heavy perfume for women in mixed spaces is discouraged as it can attract attention.`, ms: `Memakai minyak wangi digalakkan bagi lelaki pada hari Jumaat dan secara umum; minyak wangi yang tebal bagi wanita di ruang bercampur adalah tidak digalakkan kerana ia boleh menarik perhatian.`, tur: `Erkekler için Cuma günü ve genel olarak parfüm sürünmek teşvik edilir; karma ortamlarda kadınlar için ağır parfüm, dikkat çekebileceğinden hoş karşılanmaz.`, urd: `مردوں کے لیے جمعہ کے دن اور عمومی طور پر خوشبو لگانا مستحسن ہے؛ ملے جلے ماحول میں عورتوں کے لیے تیز خوشبو ناپسندیدہ ہے کیونکہ یہ توجہ کھینچ سکتی ہے۔`, ben: `পুরুষদের জন্য জুমার দিনে এবং সাধারণভাবে সুগন্ধি ব্যবহার উৎসাহিত করা হয়; মিশ্র পরিবেশে নারীদের জন্য ভারী সুগন্ধি নিরুৎসাহিত করা হয়, কারণ এটি মনোযোগ আকর্ষণ করতে পারে।`, fas: `استفاده از عطر برای مردان در جمعه و به‌طور کلی تشویق می‌شود؛ عطر سنگین برای زنان در فضاهای مختلط نامطلوب است زیرا می‌تواند توجه جلب کند.`, zh: `男子在主麻日及一般时候使用香水受到鼓励；女子在男女混杂场合使用浓香水则不受鼓励，因其可能招致注意。`, yue: `男子喺主麻日同一般時候使用香水受到鼓勵；女子喺男女混雜場合使用濃香水就唔受鼓勵，因為可能招致注意。`, ja: `男性が香水をつけることはジュムアや日常においても奨励されるが、男女が混在する場では女性の重い香水は注意を引きかねないため好ましくない。`, ru: `Использование благовоний для мужчин поощряется в пятницу и в целом; тяжёлые духи для женщин в смешанных пространствах не рекомендуются, так как могут привлекать внимание.`, es: `Se recomienda el perfume para los hombres el viernes y en general; el perfume intenso para las mujeres en espacios mixtos se desaconseja porque puede atraer atención.`, ko: `남성이 금요일과 평소에 향수를 뿌리는 것은 권장되나, 남녀가 함께 있는 공간에서 여성이 진한 향수를 뿌리는 것은 주의를 끌 수 있어 권장되지 않는다.`, ta: `ஆண்களுக்கு ஜும்ஆவின்போதும் பொதுவாகவும் வாசனை திரவியம் பூசுவது ஊக்குவிக்கப்படுகிறது; கலப்பு இடங்களில் பெண்களுக்கு கடும் வாசனை திரவியம் ஊக்கமளிக்கப்படுவதில்லை, ஏனெனில் அது கவனத்தை ஈர்க்கலாம்.`, si: `පිරිමින්ට ජුමුආ දිනයේ හා සාමාන්‍යයෙන් සුවඳ විලවුන් යෙදීම දිරිමත් කරනු ලැබේ; මිශ්‍ර අවකාශයන්හි කාන්තාවන්ට බර සුවඳ විලවුන් යෙදීම අධෛර්යමත් කරනු ලැබේ, මන්ද එය අවධානය ආකර්ෂණය කළ හැකි බැවිනි.` },
  beh_7: { en: `Children may attend. The Prophet ﷺ sometimes shortened his prayer because he heard a baby cry, out of consideration for the mother (al-Bukhari 707). Bringing children is a virtue, not a burden, when they are supervised.`, ms: `Kanak-kanak boleh hadir. Nabi ﷺ kadangkala memendekkan solat baginda kerana mendengar tangisan bayi, sebagai keprihatinan terhadap ibunya (al-Bukhari 707). Membawa anak-anak adalah suatu kebaikan, bukan bebanan, apabila mereka diawasi.`, tur: `Çocuklar katılabilir. Peygamber ﷺ, bir bebeğin ağlamasını duyduğunda annesine olan düşüncesinden dolayı namazını bazen kısaltırdı (Buhârî 707). Gözetim altında olduklarında çocukları getirmek bir yük değil, bir erdemdir.`, urd: `بچے شریک ہو سکتے ہیں۔ نبی ﷺ کبھی کبھار بچے کے رونے کی آواز سن کر ماں کا خیال رکھتے ہوئے اپنی نماز مختصر کر دیتے تھے (بخاری ۷۰۷)۔ بچوں کو ساتھ لانا، جب وہ نگرانی میں ہوں، ایک فضیلت ہے، بوجھ نہیں۔`, ben: `শিশুরা উপস্থিত হতে পারে। নবী ﷺ কখনো কখনো শিশুর কান্না শুনে মায়ের প্রতি বিবেচনা করে নামাজ সংক্ষিপ্ত করে দিতেন (বুখারি ৭০৭)। তত্ত্বাবধানে থাকলে শিশুদের নিয়ে আসা একটি সওয়াবের কাজ, বোঝা নয়।`, fas: `کودکان می‌توانند حضور یابند. پیامبر ﷺ گاهی نماز خود را به دلیل شنیدن گریه کودک، از سر ملاحظه به مادر، کوتاه می‌کرد (بخاری ۷۰۷). آوردن کودکان، وقتی زیر نظر باشند، فضیلتی است نه باری.`, zh: `儿童可以出席。先知 ﷺ 有时因听见婴儿啼哭而缩短礼拜，是出于对母亲的体谅（布哈里707）。在有人看护的情况下，带孩子来是一种美德，而非负担。`, yue: `兒童可以出席。先知 ﷺ 有時因為聽見嬰兒啼哭而縮短禮拜，係出於對母親嘅體諒（布哈里707）。喺有人睇住嘅情況下，帶小朋友嚟係一種美德，而唔係負擔。`, ja: `子供の同伴は許される。預言者 ﷺ は、赤子の泣き声を聞いて母親への配慮から礼拝を短くされることがあった（ブハーリー 707）。監督が行き届いている限り、子供を連れてくることは負担ではなく美徳である。`, ru: `Дети могут присутствовать. Пророк ﷺ иногда сокращал свою молитву, услышав плач младенца, из уважения к матери (аль-Бухари 707). Приводить детей, это достоинство, а не бремя, когда за ними присматривают.`, es: `Los niños pueden asistir. El Profeta ﷺ a veces acortaba su oración al oír llorar a un bebé, por consideración hacia la madre (al-Bukhari 707). Traer niños es una virtud, no una carga, cuando están supervisados.`, ko: `어린이도 참석할 수 있다. 예언자 ﷺ 께서는 아기 울음소리를 들으시고 어머니를 배려하여 예배를 짧게 하신 적이 있다 (알부카리 707). 감독이 이루어진다면 아이를 데려오는 것은 부담이 아니라 미덕이다.`, ta: `குழந்தைகள் கலந்துகொள்ளலாம். நபி ﷺ சில நேரங்களில் குழந்தை அழுவதைக் கேட்டு, தாய் மீது கருணை காட்டி தொழுகையைச் சுருக்கினார் (புகாரி 707). கண்காணிக்கப்படும்போது குழந்தைகளைக் கொண்டு வருவது ஒரு நல்லொழுக்கம், சுமை அல்ல.`, si: `ළමයින්ට සහභාගී විය හැක. නබි ﷺ තුමා සමහර විට කිරි දරුවෙකුගේ අඬන හඬ ඇසී මවට සලකා නමස්කාරය කෙටි කළහ (බුහාරි 707). අධීක්ෂණය කරන විට ළමයින් රැගෙන ඒම බරක් නොව ගුණයකි.` },
  beh_8: { en: `Cleanliness. He ﷺ said: "Spitting in the masjid is a sin, and its expiation is to bury it." (al-Bukhari 415). Extended today: no litter, no crumbs, mats and shoes cared for.`, ms: `Kebersihan. Baginda ﷺ bersabda: "Meludah di dalam masjid adalah suatu dosa, dan kaffarahnya ialah menimbusnya." (al-Bukhari 415). Diperluaskan pada hari ini: tiada sampah, tiada serpihan makanan, tikar dan kasut dijaga dengan baik.`, tur: `Temizlik. O ﷺ şöyle buyurdu: "Mescide tükürmek bir günahtır, kefareti onu gömmektir." (Buhârî 415). Günümüzde bu, çöp bırakmama, kırıntı bırakmama, halılara ve ayakkabılara özen gösterme şeklinde genişletilir.`, urd: `صفائی۔ آپ ﷺ نے فرمایا: "مسجد میں تھوکنا گناہ ہے، اور اس کا کفارہ اسے دفن کرنا ہے۔" (بخاری ۴۱۵)۔ آج کے دور میں اس کا دائرہ وسیع ہے: کوئی کوڑا کرکٹ نہیں، کوئی ٹکڑے نہیں، قالینوں اور جوتوں کا خیال رکھا جائے۔`, ben: `পরিচ্ছন্নতা। তিনি ﷺ বলেছেন: "মসজিদে থুতু ফেলা একটি পাপ, এবং এর কাফফারা তা মাটিচাপা দেওয়া।" (বুখারি ৪১৫)। আজকের প্রেক্ষাপটে এর পরিধি: কোনো আবর্জনা নয়, কোনো টুকরো-টাকরা নয়, মাদুর ও জুতার যত্ন নেওয়া।`, fas: `پاکیزگی. او ﷺ فرمود: «آب دهان انداختن در مسجد گناهی است، و کفاره‌ی آن دفن کردن آن است.» (بخاری ۴۱۵). امروزه گسترش‌یافته به: بدون زباله، بدون خرده‌ریز، مراقبت از حصیرها و کفش‌ها.`, zh: `清洁。先知 ﷺ 说：「在清真寺内吐痰乃是一种罪过，其赎罪之法是将其掩埋。」（布哈里415）。今日引申为：不留垃圾、不留碎屑、爱护地毯与鞋履。`, yue: `清潔。先知 ﷺ 話：「喺清真寺內吐痰係一種罪過，贖罪之法就係將佢掩埋。」（布哈里415）。今日引申為：唔留垃圾、唔留碎屑、愛護地毯同鞋履。`, ja: `清潔さ。彼 ﷺ は仰せられた。「モスクで唾を吐くことは罪であり、その償いはそれを埋めることである。」（ブハーリー 415）。今日ではこれが拡張され、ゴミを残さない、食べこぼしを残さない、マットや靴を大切に扱うことを意味する。`, ru: `Чистота. Он ﷺ сказал: «Плевать в мечети, грех, и искупление этого, закопать плевок» (аль-Бухари 415). Сегодня это расширяется: не сорить, не оставлять крошек, беречь коврики и обувь.`, es: `Limpieza. Él ﷺ dijo: «Escupir en la mezquita es un pecado, y su expiación es enterrarlo.» (al-Bukhari 415). Hoy se extiende a: no dejar basura, no dejar migas, cuidar las alfombras y los zapatos.`, ko: `청결. 그분 ﷺ 께서 말씀하셨다: "모스크에서 침을 뱉는 것은 죄이며, 그 속죄는 그것을 묻는 것이다." (알부카리 415). 오늘날 이는 쓰레기를 남기지 않고, 부스러기를 남기지 않으며, 매트와 신발을 잘 관리하는 것으로 확장된다.`, ta: `தூய்மை. அவர் ﷺ கூறினார்: "மசூதியில் துப்புவது ஒரு பாவம், அதற்கான பரிகாரம் அதை மண்ணில் புதைப்பதே." (புகாரி 415). இன்று இது விரிவாக்கப்பட்டுள்ளது: குப்பை இல்லை, துண்டுகள் இல்லை, பாய்களும் காலணிகளும் கவனிக்கப்பட வேண்டும்.`, si: `පිරිසිදුකම. උන් වහන්සේ ﷺ පැවසුවේ: "මස්ජිදයේ කෙළ ගැසීම පාපයකි, එහි වන්දිය එය වළලීමයි." (බුහාරි 415). අද එය පුළුල් කර ඇත: කසළ නොතිබිය යුතුය, කැබලි නොතිබිය යුතුය, පැදුරු හා පාවහන් රැකබලා ගත යුතුය.` },
  retreat_h: { en: `The Masjid as a Place of Retreat`, ms: `Masjid Sebagai Tempat Berkhalwat`, tur: `Bir Sığınak Olarak Mescit`, urd: `مسجد بطور اعتکاف کی جگہ`, ben: `আশ্রয়স্থল হিসেবে মসজিদ`, fas: `مسجد به‌عنوان جایگاه اعتکاف`, zh: `作为静修之所的清真寺`, yue: `作為靜修之所嘅清真寺`, ja: `隠遁の場としてのモスク`, ru: `Мечеть как место уединения`, es: `La mezquita como lugar de retiro`, ko: `은둔의 장소로서의 모스크`, ta: `தனிமைப்படுத்தலுக்கான இடமாக மசூதி`, si: `විවේකයේ ස්ථානයක් ලෙස මස්ජිදය` },
  retreat_p1: { en: `Beyond the five daily prayers, the masjid was, in the Prophet's ﷺ Madinah, the school, the parliament, the treasury, the courthouse, and the shelter of the destitute. He ﷺ himself performed i'tikaf in it every last ten nights of Ramadan.`, ms: `Selain daripada solat lima waktu, masjid, dalam Madinah Nabi ﷺ, adalah sekolah, majlis permesyuaratan, perbendaharaan, mahkamah, dan tempat perlindungan orang miskin. Baginda ﷺ sendiri melakukan iktikaf di dalamnya pada setiap sepuluh malam terakhir Ramadan.`, tur: `Beş vakit namazın ötesinde, Peygamber'in ﷺ Medine'sinde mescit; okul, meclis, hazine, mahkeme ve yoksulların sığınağıydı. O ﷺ da her Ramazan'ın son on gecesinde orada itikâfa girerdi.`, urd: `پانچ وقت کی نمازوں کے علاوہ، نبی ﷺ کے مدینہ میں مسجد اسکول، مجلسِ شوریٰ، خزانہ، عدالت، اور نادار لوگوں کی پناہ گاہ تھی۔ آپ ﷺ خود رمضان کی آخری دس راتوں میں اس میں اعتکاف کیا کرتے تھے۔`, ben: `পাঁচ ওয়াক্ত নামাজের বাইরেও, নবী ﷺ-এর মদিনায় মসজিদ ছিল বিদ্যালয়, পরিষদ, কোষাগার, আদালত, এবং নিঃস্বদের আশ্রয়স্থল। তিনি ﷺ নিজেও রমজানের প্রতি শেষ দশ রাত এতে ইতিকাফ করতেন।`, fas: `فراتر از پنج نماز روزانه، مسجد در مدینه‌ی پیامبر ﷺ، مدرسه، مجلس شورا، خزانه، دادگاه، و پناهگاه تهیدستان بود. خود او ﷺ در هر ده شب پایانی رمضان در آن اعتکاف می‌کرد.`, zh: `除每日五番拜功外，在先知 ﷺ 的麦地那，清真寺亦是学校、议会、金库、法庭，以及贫困者的庇护所。先知 ﷺ 本人每逢斋月最后十夜均在此静修（伊斯提卡夫）。`, yue: `除每日五番拜功外，喺先知 ﷺ 嘅麥地那，清真寺亦係學校、議會、金庫、法庭，以及貧困者嘅庇護所。先知 ﷺ 本人每逢齋月最後十夜都喺呢度靜修（伊斯提卡夫）。`, ja: `一日五回の礼拝を超えて、預言者 ﷺ のマディーナにおいてモスクは学校であり、議会であり、国庫であり、法廷であり、困窮者の避難所であった。彼 ﷺ 自身、ラマダーンの最後の十夜には毎年そこでイティカーフを行われた。`, ru: `Помимо пяти ежедневных молитв, мечеть в Медине Пророка ﷺ была школой, парламентом, казной, судом и приютом для нуждающихся. Сам он ﷺ совершал итикаф в ней каждые последние десять ночей Рамадана.`, es: `Más allá de las cinco oraciones diarias, la mezquita fue, en la Medina del Profeta ﷺ, la escuela, el parlamento, el tesoro, el tribunal y el refugio de los necesitados. Él mismo ﷺ realizaba i'tikaf en ella cada últimas diez noches de Ramadán.`, ko: `하루 다섯 번의 예배를 넘어, 예언자 ﷺ 의 마디나에서 모스크는 학교이자 의회, 국고, 법정, 그리고 빈곤한 자들의 피난처였다. 그분 ﷺ 께서도 라마단의 마지막 열흘 밤마다 그곳에서 이으티카프를 행하셨다.`, ta: `ஐந்து நேரத் தொழுகைகளுக்கு அப்பால், நபியின் ﷺ மதீனாவில் மசூதி பள்ளியாகவும், சபையாகவும், கருவூலமாகவும், நீதிமன்றமாகவும், ஏழைகளின் புகலிடமாகவும் இருந்தது. அவரே ﷺ ரமளானின் ஒவ்வொரு கடைசி பத்து இரவுகளிலும் அதில் இஃதிகாஃப் இருந்தார்.`, si: `දෛනික නමස්කාර පහට අමතරව, නබි ﷺ තුමාගේ මදීනාවේ මස්ජිදය පාසැලක්, පාර්ලිමේන්තුවක්, භාණ්ඩාගාරයක්, උසාවියක්, සහ දුප්පතුන්ගේ රැකවරණයක් විය. උන් වහන්සේ ﷺ තුමා ම රාමසාන් මාසයේ අවසාන රාත්‍රී දහයේදීම එහි ඉඃතිකාෆ් සිදු කළහ.` },
  retreat_p2: { en: `The Prophet ﷺ said: "The seven whom Allah will shade under His shade on a day when there is no shade but His" include "a man whose heart is attached to the masjid." (al-Bukhari 660, Muslim 1031).`, ms: `Nabi ﷺ bersabda: "Tujuh golongan yang akan dinaungi oleh Allah di bawah naungan-Nya pada hari yang tiada naungan melainkan naungan-Nya" termasuklah "seorang lelaki yang hatinya terpaut kepada masjid." (al-Bukhari 660, Muslim 1031).`, tur: `Peygamber ﷺ şöyle buyurdu: "Allah'ın, kendi gölgesinden başka gölge olmayan bir günde kendi gölgesinde barındıracağı yedi kişi"den biri de "kalbi mescide bağlı olan kişidir." (Buhârî 660, Müslim 1031).`, urd: `نبی ﷺ نے فرمایا: "سات لوگ ہیں جنہیں اللہ اپنے سائے کے دن، جب اس کے سائے کے سوا کوئی سایہ نہیں ہوگا، اپنے سائے میں جگہ دے گا" ان میں شامل ہے "وہ شخص جس کا دل مسجد سے وابستہ ہو۔" (بخاری ۶۶۰، مسلم ۱۰۳۱)۔`, ben: `নবী ﷺ বলেছেন: "সাত ব্যক্তি, যাদের আল্লাহ তাঁর ছায়ায় স্থান দেবেন এমন দিনে যখন তাঁর ছায়া ছাড়া আর কোনো ছায়া থাকবে না," তাদের মধ্যে রয়েছে "সেই ব্যক্তি যার হৃদয় মসজিদের সাথে সংযুক্ত।" (বুখারি ৬৬০, মুসলিম ১০৩১)।`, fas: `پیامبر ﷺ فرمود: «هفت کس را خداوند در روزی که سایه‌ای جز سایه‌ی او نیست، زیر سایه‌ی خویش قرار می‌دهد» و از آن جمله «مردی که دلش وابسته به مسجد است.» (بخاری ۶۶۰، مسلم ۱۰۳۱).`, zh: `先知 ﷺ 说：「在那除真主的荫庇外别无荫庇之日，真主将以其荫庇庇护七种人」，其中包括「心系清真寺之人」。（布哈里660，穆斯林1031）。`, yue: `先知 ﷺ 話：「喺嗰個除真主嘅蔭庇之外冇任何蔭庇嘅日子，真主將以其蔭庇庇護七種人」，其中包括「心繫清真寺嘅人」。（布哈里660，穆斯林1031）。`, ja: `預言者 ﷺ は仰せられた。「アッラーの陰以外に陰のない日に、アッラーがその御陰でお守りになる七種の者」の中に「心がモスクに結びついている者」がある（ブハーリー 660、ムスリム 1031）。`, ru: `Пророк ﷺ сказал: «Семерых Аллах укроет в Своей тени в день, когда не будет иной тени, кроме Его», среди них «человек, чьё сердце привязано к мечети» (аль-Бухари 660, Муслим 1031).`, es: `El Profeta ﷺ dijo: «Los siete a quienes Al-lah dará sombra bajo Su sombra en un día en que no habrá más sombra que la Suya» incluyen «a un hombre cuyo corazón está apegado a la mezquita.» (al-Bukhari 660, Muslim 1031).`, ko: `예언자 ﷺ 께서 말씀하셨다: "알라의 그늘 외에는 그늘이 없는 날, 알라께서 그분의 그늘로 덮어주실 일곱 부류" 가운데 "마음이 모스크에 매인 사람"이 있다 (알부카리 660, 무슬림 1031).`, ta: `நபி ﷺ கூறினார்: "அல்லாஹ்வின் நிழல் தவிர வேறு நிழல் இல்லாத நாளில், அல்லாஹ் தன் நிழலின் கீழ் நிழல் தரும் ஏழு பேரில்" "இதயம் மசூதியுடன் இணைந்திருக்கும் ஒருவனும்" அடங்குவான். (புகாரி 660, முஸ்லிம் 1031).`, si: `නබි ﷺ තුමා පැවසුවේ: "අල්ලාහ්ගේ සෙවණැල්ල හැර වෙනත් සෙවණැල්ලක් නොමැති දිනක ඔහුගේ සෙවණේ අහල් වන අය හත් දෙනාගෙන්" "සිත මස්ජිදයට බැඳුනු මිනිසෙකු" ද වේ. (බුහාරි 660, මුස්ලිම් 1031).` },
  retreat_p3: { en: `The full etiquette of the masjid, then, is not simply a checklist of what to do at the door. It is the disposition of one whose heart returns to the House of Allah between the prayers, whose peace lives there, and whose worldly business, worldly speech, worldly appearance, all quiet down when the sandals come off at the threshold.`, ms: `Maka adab lengkap masjid bukanlah sekadar senarai semak apa yang perlu dilakukan di pintu. Ia adalah keadaan hati seseorang yang sentiasa kembali kepada Rumah Allah di antara waktu-waktu solat, yang ketenangannya bersemayam di sana, dan yang urusan duniawi, percakapan duniawi, serta penampilan duniawinya, semuanya reda apabila kasut ditanggalkan di ambang pintu.`, tur: `Öyleyse mescidin bütünüyle edebi, kapıda yapılacaklar listesinden ibaret değildir. Bu, namazlar arasında kalbi Allah'ın Evi'ne dönen, huzuru orada yaşayan ve eşikte terlikler çıkarıldığında dünyevi işi, dünyevi sözü, dünyevi görünüşü sakinleşen kişinin ruh halidir.`, urd: `پس مسجد کے مکمل آداب محض دروازے پر کیا کرنا ہے اس کی فہرست نہیں۔ یہ اس شخص کی کیفیت ہے جس کا دل نمازوں کے درمیان بیت اللہ کی طرف لوٹتا ہے، جس کا سکون وہیں بستا ہے، اور جس کی دنیاوی کاروبار، دنیاوی گفتگو، دنیاوی ظاہری وضع، سب دہلیز پر جوتے اتارتے ہی خاموش ہو جاتی ہیں۔`, ben: `সুতরাং মসজিদের পূর্ণ আদব কেবল দরজায় কী করতে হবে তার একটি তালিকা নয়। এটি সেই ব্যক্তির অবস্থা যার হৃদয় নামাজের মাঝে আল্লাহর ঘরে ফিরে যায়, যার প্রশান্তি সেখানে বাস করে, এবং যার দুনিয়াবি ব্যবসা, দুনিয়াবি কথাবার্তা, দুনিয়াবি চেহারা, সবই দোরগোড়ায় জুতা খোলার সাথে সাথে শান্ত হয়ে যায়।`, fas: `پس آداب کامل مسجد، تنها فهرستی از کارهایی که باید در آستانه انجام داد نیست. این حالت کسی است که دلش میان نمازها به خانه‌ی خدا بازمی‌گردد، آرامشش در آنجا ساکن است، و کسب‌وکار دنیوی‌اش، سخن دنیوی‌اش، ظاهر دنیوی‌اش، همه هنگام درآوردن نعلین در آستانه آرام می‌گیرند.`, zh: `因此，清真寺的完整礼仪并非只是门口一份待办事项清单。它是这样一种心境：一个人的心在拜功之间不断返归安拉之殿，其安宁栖居于此，其世俗的事务、世俗的言语、世俗的仪表，都在门槛脱去凉鞋之际归于平静。`, yue: `所以，清真寺嘅完整禮儀並唔係只係門口一份待辦事項清單。呢個係一種心境：一個人嘅心喺拜功之間不斷返歸安拉之殿，其安寧棲居於此，其世俗嘅事務、世俗嘅言語、世俗嘅儀表，都喺門檻脫去涼鞋之際歸於平靜。`, ja: `したがって、モスクの完全な作法とは、単に戸口ですべきことのチェックリストではない。それは、礼拝と礼拝の間にも心がアッラーの家へと戻る者の心境であり、その平安がそこに住み、敷居でサンダルを脱ぐとき、世俗の用事も、世俗の言葉も、世俗の姿も、すべてが静まる者の在り方なのである。`, ru: `Итак, полный этикет мечети, это не просто перечень действий у двери. Это состояние того, чьё сердце возвращается к Дому Аллаха между молитвами, чей покой живёт там, и чьи мирские дела, мирская речь, мирской облик, всё стихает, когда сандалии снимаются у порога.`, es: `Así pues, la etiqueta completa de la mezquita no es simplemente una lista de lo que hay que hacer en la puerta. Es la disposición de quien tiene el corazón que vuelve a la Casa de Al-lah entre las oraciones, cuya paz habita allí, y cuyo negocio mundano, discurso mundano y apariencia mundana se aquietan al quitarse las sandalias en el umbral.`, ko: `따라서 모스크의 완전한 예절이란 단지 문 앞에서 해야 할 일들의 목록이 아니다. 그것은 예배와 예배 사이에도 마음이 알라의 집으로 돌아가는 이의 마음가짐이며, 그의 평안이 그곳에 깃들고, 문턱에서 샌들을 벗는 순간 세속의 일과 세속의 말, 세속의 겉모습이 모두 잦아드는 이의 자세이다.`, ta: `எனவே மசூதியின் முழுமையான ஒழுக்கம் வாசலில் என்ன செய்ய வேண்டும் என்பதற்கான ஒரு பட்டியல் மட்டுமல்ல. இது தொழுகைகளுக்கு இடையில் இதயம் அல்லாஹ்வின் இல்லத்திற்குத் திரும்பும், அமைதி அங்கே வாழும், மற்றும் தன் உலகியல் வியாபாரம், உலகியல் பேச்சு, உலகியல் தோற்றம் அனைத்தும் வாசற்படியில் செருப்புகளை கழற்றும்போது அமைதியடையும் ஒருவரின் மனநிலையாகும்.`, si: `එබැවින් මස්ජිදයේ පූර්ණ ආචාර ධර්ම හුදෙක් දොරකඩදී කළ යුතු දේ ලැයිස්තුවක් නොවේ. එය නමස්කාර අතරතුර සිත අල්ලාහ්ගේ නිවසට නැවත හැරෙන, ඔහුගේ සාමය එහි වාසය කරන, සහ ලෞකික ව්‍යාපාරය, ලෞකික කථනය, ලෞකික පෙනුම, සියල්ල එළිපත්තෙහි සපත්තු ගැලවෙන විට නිහඬ වන කෙනෙකුගේ මනෝභාවයයි.` },
  label_transliteration: { en: `Transliteration`, ms: `Transliterasi`, tur: `Transliterasyon`, urd: `تلفظ`, ben: `প্রতিবর্ণীকরণ`, fas: `آوانویسی`, zh: `音译`, yue: `音譯`, ja: `音訳`, ru: `Транслитерация`, es: `Transliteración`, ko: `음역`, ta: `ஒலிபெயர்ப்பு`, si: `අක්ෂර පරිවර්තනය` },
  label_meaning: { en: `Meaning`, ms: `Maksud`, tur: `Anlamı`, urd: `مفہوم`, ben: `অর্থ`, fas: `معنی`, zh: `释义`, yue: `釋義`, ja: `意味`, ru: `Значение`, es: `Significado`, ko: `의미`, ta: `பொருள்`, si: `අර්ථය` },
} as const satisfies Record<string, LangMap>;

export type MasjidContentKey = keyof typeof MASJID_CONTENT;
